  LT_DLMUTEX_LOCK ();

  if (++initialized == 1)
    {
      handles = 0;
      user_search_path = 0; 

#if HAVE_LIBDL
      errors += lt_dlloader_add (lt_dlloader_next (0), &sys_dl, "dlopen");
#endif
