static struct sock *tcp_v6_syn_recv_sock(const struct sock *sk, struct sk_buff *skb,
					 struct request_sock *req,
					 struct dst_entry *dst,
					 struct request_sock *req_unhash,
					 bool *own_req)
{
	struct inet_request_sock *ireq;
	struct ipv6_pinfo *newnp;
	const struct ipv6_pinfo *np = inet6_sk(sk);
	struct ipv6_txoptions *opt;
	struct tcp6_sock *newtcp6sk;
	struct inet_sock *newinet;
	struct tcp_sock *newtp;
	struct sock *newsk;
#ifdef CONFIG_TCP_MD5SIG
	struct tcp_md5sig_key *key;
#endif
	struct flowi6 fl6;

	if (skb->protocol == htons(ETH_P_IP)) {

		newsk = tcp_v4_syn_recv_sock(sk, skb, req, dst,
					     req_unhash, own_req);

		if (!newsk)
			return NULL;

		newtcp6sk = (struct tcp6_sock *)newsk;
		inet_sk(newsk)->pinet6 = &newtcp6sk->inet6;

		newinet = inet_sk(newsk);
		newnp = inet6_sk(newsk);
		newtp = tcp_sk(newsk);

		memcpy(newnp, np, sizeof(struct ipv6_pinfo));

		newnp->saddr = newsk->sk_v6_rcv_saddr;

		inet_csk(newsk)->icsk_af_ops = &ipv6_mapped;
		newsk->sk_backlog_rcv = tcp_v4_do_rcv;
#ifdef CONFIG_TCP_MD5SIG
 		newtp->af_specific = &tcp_sock_ipv6_mapped_specific;
 #endif

 		newnp->ipv6_ac_list = NULL;
 		newnp->ipv6_fl_list = NULL;
 		newnp->pktoptions  = NULL;
		newnp->opt	   = NULL;
		newnp->mcast_oif   = tcp_v6_iif(skb);
		newnp->mcast_hops  = ipv6_hdr(skb)->hop_limit;
		newnp->rcv_flowinfo = ip6_flowinfo(ipv6_hdr(skb));
		if (np->repflow)
			newnp->flow_label = ip6_flowlabel(ipv6_hdr(skb));


		tcp_sync_mss(newsk, inet_csk(newsk)->icsk_pmtu_cookie);

		return newsk;
	}

	ireq = inet_rsk(req);

	if (sk_acceptq_is_full(sk))
		goto out_overflow;

	if (!dst) {
		dst = inet6_csk_route_req(sk, &fl6, req, IPPROTO_TCP);
		if (!dst)
			goto out;
	}

	newsk = tcp_create_openreq_child(sk, req, skb);
	if (!newsk)
		goto out_nonewsk;


	newsk->sk_gso_type = SKB_GSO_TCPV6;
	ip6_dst_store(newsk, dst, NULL, NULL);
	inet6_sk_rx_dst_set(newsk, skb);

	newtcp6sk = (struct tcp6_sock *)newsk;
	inet_sk(newsk)->pinet6 = &newtcp6sk->inet6;

	newtp = tcp_sk(newsk);
	newinet = inet_sk(newsk);
	newnp = inet6_sk(newsk);

	memcpy(newnp, np, sizeof(struct ipv6_pinfo));

	newsk->sk_v6_daddr = ireq->ir_v6_rmt_addr;
	newnp->saddr = ireq->ir_v6_loc_addr;
	newsk->sk_v6_rcv_saddr = ireq->ir_v6_loc_addr;
	newsk->sk_bound_dev_if = ireq->ir_iif;

 	newinet->inet_opt = NULL;
 	newnp->ipv6_ac_list = NULL;
 	newnp->ipv6_fl_list = NULL;

	newnp->rxopt.all = np->rxopt.all;

	newnp->pktoptions = NULL;
	newnp->opt	  = NULL;
	newnp->mcast_oif  = tcp_v6_iif(skb);
	newnp->mcast_hops = ipv6_hdr(skb)->hop_limit;
	newnp->rcv_flowinfo = ip6_flowinfo(ipv6_hdr(skb));
	if (np->repflow)
		newnp->flow_label = ip6_flowlabel(ipv6_hdr(skb));

	opt = ireq->ipv6_opt;
	if (!opt)
		opt = rcu_dereference(np->opt);
	if (opt) {
		opt = ipv6_dup_options(newsk, opt);
		RCU_INIT_POINTER(newnp->opt, opt);
	}
	inet_csk(newsk)->icsk_ext_hdr_len = 0;
	if (opt)
		inet_csk(newsk)->icsk_ext_hdr_len = opt->opt_nflen +
						    opt->opt_flen;

	tcp_ca_openreq_child(newsk, dst);

	tcp_sync_mss(newsk, dst_mtu(dst));
	newtp->advmss = tcp_mss_clamp(tcp_sk(sk), dst_metric_advmss(dst));

	tcp_initialize_rcv_mss(newsk);

	newinet->inet_daddr = newinet->inet_saddr = LOOPBACK4_IPV6;
	newinet->inet_rcv_saddr = LOOPBACK4_IPV6;

#ifdef CONFIG_TCP_MD5SIG
	key = tcp_v6_md5_do_lookup(sk, &newsk->sk_v6_daddr);
	if (key) {
		tcp_md5_do_add(newsk, (union tcp_md5_addr *)&newsk->sk_v6_daddr,
			       AF_INET6, key->key, key->keylen,
			       sk_gfp_mask(sk, GFP_ATOMIC));
	}
#endif

	if (__inet_inherit_port(sk, newsk) < 0) {
		inet_csk_prepare_forced_close(newsk);
		tcp_done(newsk);
		goto out;
	}
	*own_req = inet_ehash_nolisten(newsk, req_to_sk(req_unhash));
	if (*own_req) {
		tcp_move_syn(newtp, req);

		if (ireq->pktopts) {
			newnp->pktoptions = skb_clone(ireq->pktopts,
						      sk_gfp_mask(sk, GFP_ATOMIC));
			consume_skb(ireq->pktopts);
			ireq->pktopts = NULL;
			if (newnp->pktoptions) {
				tcp_v6_restore_cb(newnp->pktoptions);
				skb_set_owner_r(newnp->pktoptions, newsk);
			}
		}
	}

	return newsk;

out_overflow:
	__NET_INC_STATS(sock_net(sk), LINUX_MIB_LISTENOVERFLOWS);
out_nonewsk:
	dst_release(dst);
out:
	tcp_listendrop(sk);
	return NULL;
}

cJSON *cJSON_CreateStringArray( const char **strings, int count )
{
	int i;
	cJSON *n = 0, *p = 0, *a = cJSON_CreateArray();
	for ( i = 0; a && i < count; ++i ) {
		n = cJSON_CreateString( strings[i] );
		if ( ! i )
			a->child = n;
		else
			suffix_object( p, n );
		p = n;
	}
	return a;
 }

SchedulerObject::setAttribute(std::string key,
							  std::string name,
							  std::string value,
                                                          std::string &text)
 {
        PROC_ID id = getProcByString(key.c_str());
       if (id.cluster < 0 || id.proc < 0) {
                dprintf(D_FULLDEBUG, "SetAttribute: Failed to parse id: %s\n", key.c_str());
                text = "Invalid Id";
                return false;
	}

	if (isSubmissionChange(name.c_str())) {
		text = "Changes to submission name not allowed";
		return false;
	}

	if (isKeyword(name.c_str())) {
		text = "Attribute name is reserved: " + name;
		return false;
	}

	if (!isValidAttributeName(name,text)) {
		return false;
	}

	if (::SetAttribute(id.cluster,
					   id.proc,
					   name.c_str(),
					   value.c_str())) {
		text = "Failed to set attribute " + name + " to " + value;
		return false;
	}

	return true;
}

push_decoder_state (DECODER_STATE ds)
{
  if (ds->idx >= ds->stacksize)
    {
     fprintf (stderr, "ERROR: decoder stack overflow!\n");
     abort ();
    }
  ds->stack[ds->idx++] = ds->cur;
}

gs_interp_init(i_ctx_t **pi_ctx_p, const ref *psystem_dict,
               gs_dual_memory_t *dmem)
{
    gs_context_state_t *pcst = 0;
    int code = context_state_alloc(&pcst, psystem_dict, dmem);
    if (code >= 0) {
        code = context_state_load(pcst);
        if (code < 0) {
            context_state_free(pcst);
            pcst = NULL;
        }
    }

    if (code < 0)
        lprintf1("Fatal error %d in gs_interp_init!\n", code);
    *pi_ctx_p = pcst;

    return code;
}

main( int    argc,
      char*  argv[] )
{
  int    old_ptsize, orig_ptsize, file;
  int    first_glyph = 0;
  int    XisSetup = 0;
  char*  execname;
  int    option;
  int    file_loaded;

  grEvent  event;


  execname = ft_basename( argv[0] );

  while ( 1 )
  {
    option = getopt( argc, argv, "d:e:f:r:" );

    if ( option == -1 )
      break;

    switch ( option )
    {
    case 'd':
      parse_design_coords( optarg );
      break;

    case 'e':
      encoding = (FT_Encoding)make_tag( optarg );
      break;

    case 'f':
      first_glyph = atoi( optarg );
      break;

    case 'r':
      res = atoi( optarg );
      if ( res < 1 )
        usage( execname );
      break;

    default:
      usage( execname );
      break;
    }
  }

  argc -= optind;
  argv += optind;

  if ( argc <= 1 )
    usage( execname );

  if ( sscanf( argv[0], "%d", &orig_ptsize ) != 1 )
    orig_ptsize = 64;

  file = 1;

  error = FT_Init_FreeType( &library );
  if ( error )
    PanicZ( "Could not initialize FreeType library" );

NewFile:
  ptsize      = orig_ptsize;
  hinted      = 1;
  file_loaded = 0;

  error = FT_New_Face( library, argv[file], 0, &face );
  if ( error )
    goto Display_Font;

  if ( encoding != FT_ENCODING_NONE )
  {
    error = FT_Select_Charmap( face, encoding );
    if ( error )
      goto Display_Font;
  }

  error = FT_Get_MM_Var( face, &multimaster );
  if ( error )
    goto Display_Font;

  {
    int  n;


    for ( n = 0; n < (int)multimaster->num_axis; n++ )
    {
      design_pos[n] = n < requested_cnt ? requested_pos[n]
                                        : multimaster->axis[n].def;
      if ( design_pos[n] < multimaster->axis[n].minimum )
        design_pos[n] = multimaster->axis[n].minimum;
      else if ( design_pos[n] > multimaster->axis[n].maximum )
        design_pos[n] = multimaster->axis[n].maximum;
    }
  }

  error = FT_Set_Var_Design_Coordinates( face,
                                         multimaster->num_axis,
                                         design_pos );
  if ( error )
    goto Display_Font;

  file_loaded++;

  Reset_Scale( ptsize );

  num_glyphs = face->num_glyphs;
  glyph      = face->glyph;
  size       = face->size;

Display_Font:
  if ( !XisSetup )
  {
    XisSetup = 1;
    Init_Display();
  }

  grSetTitle( surface, "FreeType Glyph Viewer - press F1 for help" );
  old_ptsize = ptsize;

  if ( file_loaded >= 1 )
  {
    Fail = 0;
    Num  = first_glyph;

    if ( Num >= num_glyphs )
      Num = num_glyphs - 1;

    if ( Num < 0 )
      Num = 0;
  }

  for ( ;; )
  {
    int  key;


    Clear_Display();

    if ( file_loaded >= 1 )
    {
      switch ( render_mode )
      {
      case 0:
        Render_Text( Num );
        break;

      default:
         Render_All( Num, ptsize );
       }

      sprintf( Header, "%s %s (file %s)",
                        face->family_name,
                        face->style_name,
                        ft_basename( argv[file] ) );

      if ( !new_header )
        new_header = Header;

      grWriteCellString( &bit, 0, 0, new_header, fore_color );
      new_header = 0;

      sprintf( Header, "axis: " );
      {
        int  n;


        for ( n = 0; n < (int)multimaster->num_axis; n++ )
        {
          char  temp[32];


          sprintf( temp, "  %s:%g",
                         multimaster->axis[n].name,
                         design_pos[n]/65536. );
          strcat( Header, temp );
        }
      }
      grWriteCellString( &bit, 0, 16, Header, fore_color );

      sprintf( Header, "at %d points, first glyph = %d",
                       ptsize,
                       Num );
     }
     else
     {
      sprintf( Header, "%s: not an MM font file, or could not be opened",
                        ft_basename( argv[file] ) );
     }
    grWriteCellString( &bit, 0, 8, Header, fore_color );
    grRefreshSurface( surface );

    grListenSurface( surface, 0, &event );
    if ( !( key = Process_Event( &event ) ) )
      goto End;

    if ( key == 'n' )
    {
      if ( file_loaded >= 1 )
        FT_Done_Face( face );

      if ( file < argc - 1 )
        file++;

      goto NewFile;
    }

    if ( key == 'p' )
    {
      if ( file_loaded >= 1 )
        FT_Done_Face( face );

      if ( file > 1 )
        file--;

      goto NewFile;
    }

    if ( ptsize != old_ptsize )
    {
      Reset_Scale( ptsize );

      old_ptsize = ptsize;
    }
  }

End:
  grDoneSurface( surface );
  grDoneDevices();

  free            ( multimaster );
  FT_Done_Face    ( face        );
  FT_Done_FreeType( library     );

  printf( "Execution completed successfully.\n" );
  printf( "Fails = %d\n", Fail );

  exit( 0 );      
  return 0;       
}

