 static size_t TrimTrailingSpaces ( char * firstChar, size_t origLen )
 {
	if ( origLen == 0 ) return 0;

 	char * lastChar  = firstChar + origLen - 1;
 	if ( (*lastChar != ' ') && (*lastChar != 0) ) return origLen;	

	while ( (firstChar <= lastChar) && ((*lastChar == ' ') || (*lastChar == 0)) ) --lastChar;

	XMP_Assert ( (lastChar == firstChar-1) ||
				 ((lastChar >= firstChar) && (*lastChar != ' ') && (*lastChar != 0)) );

	size_t newLen = (size_t)((lastChar+1) - firstChar);
	XMP_Assert ( newLen <= origLen );

	if ( newLen < origLen ) {
		++lastChar;
		*lastChar = 0;
	}

	return newLen;

}

bool MatchFilter::MatchesCookie(
    const net::CookieMonster::CookieListPair& cookie_pair) {
  const net::CookieMonster::CanonicalCookie& cookie = cookie_pair.second;
 if (!MatchesString(keys::kNameKey, cookie.Name()))
     return false;
 if (!MatchesDomain(cookie_pair.first))
     return false;
 if (!MatchesString(keys::kPathKey, cookie.Path()))
     return false;
 if (!MatchesBoolean(keys::kSecureKey, cookie.IsSecure()))
     return false;
 if (!MatchesBoolean(keys::kSessionKey, !cookie.DoesExpire()))
     return false;
 return true;
}

