 static void add_bytes_l2_c(uint8_t *dst, uint8_t *src1, uint8_t *src2, int w)
 {
     long i;
    for (i = 0; i <= w - sizeof(long); i += sizeof(long)) {
         long a = *(long *)(src1 + i);
         long b = *(long *)(src2 + i);
         *(long *)(dst + i) = ((a & pb_7f) + (b & pb_7f)) ^ ((a ^ b) & pb_80);
    }
    for (; i < w; i++)
        dst[i] = src1[i] + src2[i];
}

void WebSocketExperimentRunner::DoLoop() {
  if (next_state_ == STATE_NONE) {
    if (task_.get()) {
     AddRef();  
      task_->Cancel();
    }
    return;
 }

 State state = next_state_;
 task_state_ = STATE_NONE;
 next_state_ = STATE_NONE;

 switch (state) {
   case STATE_IDLE:
     task_.reset();
     next_state_ = STATE_RUN_WS;
     ChromeThread::PostDelayedTask(
         ChromeThread::IO,
         FROM_HERE,
         NewRunnableMethod(this, &WebSocketExperimentRunner::DoLoop),
         config_.next_delay_ms);
     break;
   case STATE_RUN_WS:
   case STATE_RUN_WSS:
   case STATE_RUN_WS_NODEFAULT_PORT:
   case STATE_RUN_WS_DRAFT75:
   case STATE_RUN_WSS_DRAFT75:
   case STATE_RUN_WS_NODEFAULT_PORT_DRAFT75:
     task_.reset(new WebSocketExperimentTask(
         config_.ws_config[state - STATE_RUN_WS], &task_callback_));
     task_state_ = state;
     if (static_cast<State>(state + 1) == NUM_STATES)
       next_state_ = STATE_IDLE;
     else
       next_state_ = static_cast<State>(state + 1);
     break;
   default:
     NOTREACHED();
     break;
 }
 if (task_.get())
   task_->Run();
}

znoaccess(i_ctx_t *i_ctx_p)
{
    os_ptr op = osp;

    check_op(1);
    if (r_has_type(op, t_dictionary)) {
        ref *aop = dict_access_ref(op);

        if (!r_has_attrs(aop, a_write)) {
            if (!r_has_attrs(aop, a_read) && !r_has_attrs(aop, a_execute)) {
                return 0;
            }
            return_error(gs_error_invalidaccess);
        }

        if (dict_is_permanent_on_dstack(op))
            return_error(gs_error_invalidaccess);
    }
    return access_check(i_ctx_p, 0, true);
}

static uint64_t ahci_mem_read(void *opaque, hwaddr addr,
                              unsigned size)
{
    AHCIState *s = opaque;
    uint32_t val = 0;

    if (addr < AHCI_GENERIC_HOST_CONTROL_REGS_MAX_ADDR) {
        switch (addr) {
        case HOST_CAP:
            val = s->control_regs.cap;
            break;
        case HOST_CTL:
            val = s->control_regs.ghc;
            break;
        case HOST_IRQ_STAT:
            val = s->control_regs.irqstatus;
            break;
        case HOST_PORTS_IMPL:
            val = s->control_regs.impl;
            break;
        case HOST_VERSION:
            val = s->control_regs.version;
            break;
        }

        DPRINTF(-1, "(addr 0x%08X), val 0x%08X\n", (unsigned) addr, val);
    } else if ((addr >= AHCI_PORT_REGS_START_ADDR) &&
               (addr < (AHCI_PORT_REGS_START_ADDR +
                (s->ports * AHCI_PORT_ADDR_OFFSET_LEN)))) {
        val = ahci_port_read(s, (addr - AHCI_PORT_REGS_START_ADDR) >> 7,
                             addr & AHCI_PORT_ADDR_OFFSET_MASK);
    }

    return val;
}

