zfile(i_ctx_t *i_ctx_p)
{
    os_ptr op = osp;
    char file_access[4];
    gs_parsed_file_name_t pname;
    int code = parse_file_access_string(op, file_access);
    stream *s;

    if (code < 0)
        return code;
    code = parse_file_name(op-1, &pname, i_ctx_p->LockFilePermissions, imemory);
    if (code < 0)
        return code;
    if (pname.iodev && pname.iodev->dtype == iodev_dtype_stdio) {
        bool statement = (strcmp(pname.iodev->dname, "%statementedit%") == 0);
        bool lineedit = (strcmp(pname.iodev->dname, "%lineedit%") == 0);
        if (pname.fname)
            return_error(gs_error_invalidfileaccess);
        if (statement || lineedit) {
            gx_io_device *indev = gs_findiodevice(imemory,
                                                  (const byte *)"%stdin", 6);
            stream *ins;
            if (strcmp(file_access, "r"))
                return_error(gs_error_invalidfileaccess);
            indev->state = i_ctx_p;
            code = (indev->procs.open_device)(indev, file_access, &ins, imemory);
            indev->state = 0;
            if (code < 0)
                return code;
            check_ostack(2);
            push(2);
            make_stream_file(op - 3, ins, file_access);
            make_bool(op-2, statement);
            make_int(op-1, 0);
            make_string(op, icurrent_space, 0, NULL);
            return zfilelineedit(i_ctx_p);
        }
        pname.iodev->state = i_ctx_p;
        code = (*pname.iodev->procs.open_device)(pname.iodev,
                                                 file_access, &s, imemory);
        pname.iodev->state = NULL;
    } else {
        if (pname.iodev == NULL)
            pname.iodev = iodev_default(imemory);
        code = zopen_file(i_ctx_p, &pname, file_access, &s, imemory);
    }
    if (code < 0)
        return code;
    code = ssetfilename(s, op[-1].value.const_bytes, r_size(op - 1));
    if (code < 0) {
        sclose(s);
        return_error(gs_error_VMerror);
    }
    make_stream_file(op - 1, s, file_access);
    pop(1);
    return code;
}

zcallbeginpage(i_ctx_t *i_ctx_p)
{
    os_ptr op = osp;
    gx_device *dev = gs_currentdevice(igs);

    check_type(*op, t_integer);
    if ((dev = (*dev_proc(dev, get_page_device))(dev)) != 0) {
        int code = (*dev->page_procs.begin_page)(dev, igs);

        if (code < 0)
            return code;
    }
    pop(1);
    return 0;
}

delete_policy_2_svc(dpol_arg *arg, struct svc_req *rqstp)
 {
     static generic_ret              ret;
     char                            *prime_arg;
    gss_buffer_desc                 client_name,
        service_name;
     OM_uint32                       minor_stat;
     kadm5_server_handle_t           handle;
     const char                      *errmsg = NULL;

    xdr_free(xdr_generic_ret, &ret);

    if ((ret.code = new_server_handle(arg->api_version, rqstp, &handle)))
        goto exit_func;

    if ((ret.code = check_handle((void *)handle)))
        goto exit_func;

    ret.api_version = handle->api_version;

    if (setup_gss_names(rqstp, &client_name, &service_name) < 0) {
        ret.code = KADM5_FAILURE;
        goto exit_func;
    }
    prime_arg = arg->name;

    if (CHANGEPW_SERVICE(rqstp) || !kadm5int_acl_check(handle->context,
                                                       rqst2name(rqstp),
                                                       ACL_DELETE, NULL, NULL)) {
        log_unauth("kadm5_delete_policy", prime_arg,
                   &client_name, &service_name, rqstp);
        ret.code = KADM5_AUTH_DELETE;
    } else {
        ret.code = kadm5_delete_policy((void *)handle, arg->name);
        if( ret.code != 0 )
            errmsg = krb5_get_error_message(handle->context, ret.code);

        log_done("kadm5_delete_policy",
                 ((prime_arg == NULL) ? "(null)" : prime_arg), errmsg,
                 &client_name, &service_name, rqstp);

         if (errmsg != NULL)
             krb5_free_error_message(handle->context, errmsg);
     }
     gss_release_buffer(&minor_stat, &client_name);
     gss_release_buffer(&minor_stat, &service_name);
exit_func:
     free_server_handle(handle);
     return &ret;
 }

bool SetImeConfig(const std::string& section,
                  const std::string& config_name,
                  const ImeConfigValue& value) {
   if (!IBusConnectionsAreAlive()) {
     LOG(ERROR) << "SetImeConfig: IBus connection is not alive";
    return false;
  }

  bool is_preload_engines = false;

  std::vector<std::string> string_list;
  if ((value.type == ImeConfigValue::kValueTypeStringList) &&
      (section == kGeneralSectionName) &&
      (config_name == kPreloadEnginesConfigName)) {
    FilterInputMethods(value.string_list_value, &string_list);
    is_preload_engines = true;
  } else {
    string_list = value.string_list_value;
  }

  GVariant* variant = NULL;
  switch (value.type) {
    case ImeConfigValue::kValueTypeString:
      variant = g_variant_new_string(value.string_value.c_str());
      break;
    case ImeConfigValue::kValueTypeInt:
      variant = g_variant_new_int32(value.int_value);
      break;
    case ImeConfigValue::kValueTypeBool:
      variant = g_variant_new_boolean(value.bool_value);
      break;
    case ImeConfigValue::kValueTypeStringList:
      GVariantBuilder variant_builder;
      g_variant_builder_init(&variant_builder, G_VARIANT_TYPE("as"));
      const size_t size = string_list.size();  
      for (size_t i = 0; i < size; ++i) {
        g_variant_builder_add(&variant_builder, "s", string_list[i].c_str());
      }
      variant = g_variant_builder_end(&variant_builder);
      break;
  }

  if (!variant) {
    LOG(ERROR) << "SetImeConfig: variant is NULL";
    return false;
  }
  DCHECK(g_variant_is_floating(variant));

  ibus_config_set_value_async(ibus_config_,
                              section.c_str(),
                              config_name.c_str(),
                              variant,
                              -1,  
                              NULL,  
                              SetImeConfigCallback,
                              g_object_ref(ibus_config_));


   if (is_preload_engines) {
    DLOG(INFO) << "SetImeConfig: " << section << "/" << config_name
               << ": " << value.ToString();
   }
   return true;
 }

