PHP_FUNCTION(mcrypt_module_open)
{
	char *cipher, *cipher_dir;
	char *mode,   *mode_dir;
	int   cipher_len, cipher_dir_len;
 	int   mode_len,   mode_dir_len;
 	MCRYPT td;
 	php_mcrypt *pm;
 	if (zend_parse_parameters (ZEND_NUM_ARGS() TSRMLS_CC, "ssss",
 		&cipher, &cipher_len, &cipher_dir, &cipher_dir_len,
 		&mode,   &mode_len,   &mode_dir,   &mode_dir_len)) {
 		return;
 	}
 	td = mcrypt_module_open (
 		cipher,
 		cipher_dir_len > 0 ? cipher_dir : MCG(algorithms_dir),
		mode, 
 		mode_dir_len > 0 ? mode_dir : MCG(modes_dir)
 	);

	if (td == MCRYPT_FAILED) {
		php_error_docref(NULL TSRMLS_CC, E_WARNING, "Could not open encryption module");
		RETURN_FALSE;
	} else {
		pm = emalloc(sizeof(php_mcrypt));
		pm->td = td;
		pm->init = 0;
		ZEND_REGISTER_RESOURCE(return_value, pm, le_mcrypt);
	}
}

virtual bool SetImeConfig(const std::string& section,
                          const std::string& config_name,
                         const ImeConfigValue& value) {
  if (section == language_prefs::kGeneralSectionName &&
      config_name == language_prefs::kPreloadEnginesConfigName &&
     value.type == ImeConfigValue::kValueTypeStringList) {
    active_input_method_ids_ = value.string_list_value;
  }

 MaybeStartInputMethodDaemon(section, config_name, value);

 const ConfigKeyType key = std::make_pair(section, config_name);
 current_config_values_[key] = value;
 if (ime_connected_) {
   pending_config_requests_[key] = value;
   FlushImeConfig();
 }

 MaybeStopInputMethodDaemon(section, config_name, value);
 MaybeChangeCurrentKeyboardLayout(section, config_name, value);
  return pending_config_requests_.empty();
}

