	tboot_probe();

	map_vsyscall();

	generic_apic_probe();

	early_quirks();

	acpi_boot_init();
	sfi_init();
	x86_dtb_init();

	if (smp_found_config)
		get_smp_config();

	prefill_possible_map();

	init_cpu_to_node();

	init_apic_mappings();
	io_apic_init_mappings();

	kvm_guest_init();

	e820_reserve_resources();
