_dbus_connect_exec (const char     *path,
                    char *const    argv[],
                    DBusError      *error)
{
  int fds[2];
  pid_t pid;

  _DBUS_ASSERT_ERROR_IS_CLEAR (error);

  _dbus_verbose ("connecting to process %s\n", path);

  if (socketpair (AF_UNIX, SOCK_STREAM
#ifdef SOCK_CLOEXEC
                  |SOCK_CLOEXEC
#endif
                  , 0, fds) < 0)
    {
      dbus_set_error (error,
                      _dbus_error_from_errno (errno),
                      "Failed to create socket pair: %s",
                      _dbus_strerror (errno));
      return -1;
    }

  _dbus_fd_set_close_on_exec (fds[0]);
  _dbus_fd_set_close_on_exec (fds[1]);

  pid = fork ();
  if (pid < 0)
    {
      dbus_set_error (error,
                      _dbus_error_from_errno (errno),
                      "Failed to fork() to call %s: %s",
                      path, _dbus_strerror (errno));
      close (fds[0]);
      close (fds[1]);
      return -1;
    }

  if (pid == 0)
    {
      close (fds[0]);

      dup2 (fds[1], STDIN_FILENO);
      dup2 (fds[1], STDOUT_FILENO);

      if (fds[1] != STDIN_FILENO &&
          fds[1] != STDOUT_FILENO)
        close (fds[1]);


      _dbus_close_all ();

      execvp (path, argv);

      fprintf (stderr, "Failed to execute process %s: %s\n", path, _dbus_strerror (errno));

      _exit(1);
    }

  close (fds[1]);

  if (!_dbus_set_fd_nonblocking (fds[0], error))
    {
      _DBUS_ASSERT_ERROR_IS_SET (error);

      close (fds[0]);
      return -1;
    }

  return fds[0];
}

t42_parse_sfnts( T42_Face    face,
                 T42_Loader  loader )
{
  T42_Parser  parser = &loader->parser;
  FT_Memory   memory = parser->root.memory;
  FT_Byte*    cur;
  FT_Byte*    limit  = parser->root.limit;
  FT_Error    error;
  FT_Int      num_tables = 0;
  FT_ULong    count, ttf_size = 0;

  FT_Long     n, string_size, old_string_size, real_size;
  FT_Byte*    string_buf = NULL;
  FT_Bool     allocated  = 0;

  T42_Load_Status  status;



  T1_Skip_Spaces( parser );

  if ( parser->root.cursor >= limit || *parser->root.cursor++ != '[' )
  {
    FT_ERROR(( "t42_parse_sfnts: can't find begin of sfnts vector\n" ));
    error = FT_THROW( Invalid_File_Format );
    goto Fail;
  }

  T1_Skip_Spaces( parser );
  status          = BEFORE_START;
  string_size     = 0;
  old_string_size = 0;
  count           = 0;

  while ( parser->root.cursor < limit )
  {
    cur = parser->root.cursor;

    if ( *cur == ']' )
    {
      parser->root.cursor++;
      goto Exit;
    }

    else if ( *cur == '<' )
    {
      T1_Skip_PS_Token( parser );
      if ( parser->root.error )
        goto Exit;

      string_size = (FT_Long)( ( parser->root.cursor - cur - 2 + 1 ) / 2 );
      if ( FT_REALLOC( string_buf, old_string_size, string_size ) )
        goto Fail;

      allocated = 1;

      parser->root.cursor = cur;
      (void)T1_ToBytes( parser, string_buf, string_size, &real_size, 1 );
      old_string_size = string_size;
      string_size = real_size;
    }

    else if ( ft_isdigit( *cur ) )
    {
      if ( allocated )
      {
        FT_ERROR(( "t42_parse_sfnts: "
                   "can't handle mixed binary and hex strings\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }

      string_size = T1_ToInt( parser );
      if ( string_size < 0 )
      {
        FT_ERROR(( "t42_parse_sfnts: invalid string size\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }

      T1_Skip_PS_Token( parser );             
      if ( parser->root.error )
        return;

      string_buf = parser->root.cursor + 1;   

      if ( limit - parser->root.cursor < string_size )
      {
        FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }
      else
        parser->root.cursor += string_size + 1;
    }

    if ( !string_buf )
    {
      FT_ERROR(( "t42_parse_sfnts: invalid data in sfnts array\n" ));
      error = FT_THROW( Invalid_File_Format );
      goto Fail;
    }

    if ( ( string_size & 1 ) && string_buf[string_size - 1] == 0 )
      string_size--;

    if ( !string_size )
    {
      FT_ERROR(( "t42_parse_sfnts: invalid string\n" ));
      error = FT_THROW( Invalid_File_Format );
      goto Fail;
    }

    for ( n = 0; n < string_size; n++ )
    {
      switch ( status )
      {
      case BEFORE_START:
        if ( count < 12 )
        {
          face->ttf_data[count++] = string_buf[n];
          continue;
        }
        else
        {
          num_tables = 16 * face->ttf_data[4] + face->ttf_data[5];
          status     = BEFORE_TABLE_DIR;
          ttf_size   = 12 + 16 * num_tables;

          if ( FT_REALLOC( face->ttf_data, 12, ttf_size ) )
            goto Fail;
        }

      case BEFORE_TABLE_DIR:
        if ( count < ttf_size )
        {
          face->ttf_data[count++] = string_buf[n];
          continue;
        }
        else
        {
          int       i;
          FT_ULong  len;


          for ( i = 0; i < num_tables; i++ )
          {
            FT_Byte*  p = face->ttf_data + 12 + 16 * i + 12;


            len = FT_PEEK_ULONG( p );

            ttf_size += ( len + 3 ) & ~3;
          }

          status         = OTHER_TABLES;
          face->ttf_size = ttf_size;

          if ( FT_REALLOC( face->ttf_data, 12 + 16 * num_tables,
                           ttf_size + 1 ) )
            goto Fail;
        }

      case OTHER_TABLES:
        if ( count >= ttf_size )
        {
          FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
          error = FT_THROW( Invalid_File_Format );
          goto Fail;
        }
        face->ttf_data[count++] = string_buf[n];
      }
    }

    T1_Skip_Spaces( parser );
  }

  error = FT_THROW( Invalid_File_Format );

Fail:
  parser->root.error = error;

Exit:
  if ( allocated )
    FT_FREE( string_buf );
}

static void xhci_complete(USBPort *port, USBPacket *packet)
{
    XHCITransfer *xfer = container_of(packet, XHCITransfer, packet);

    if (packet->status == USB_RET_REMOVE_FROM_QUEUE) {
        xhci_ep_nuke_one_xfer(xfer, 0);
        return;
    }
    xhci_try_complete_packet(xfer);
    xhci_kick_epctx(xfer->epctx, xfer->streamid);
    if (xfer->complete) {
        xhci_ep_free_xfer(xfer);
    }
}

int ZLIB_INTERNAL inflate_table(type, lens, codes, table, bits, work)
codetype type;
unsigned short FAR *lens;
unsigned codes;
code FAR * FAR *table;
unsigned FAR *bits;
unsigned short FAR *work;
{
    unsigned len;               
    unsigned sym;               
    unsigned min, max;          
    unsigned root;              
    unsigned curr;              
    unsigned drop;              
    int left;                   
    unsigned used;              
    unsigned huff;              
    unsigned incr;              
    unsigned fill;              
    unsigned low;               
    unsigned mask;              
    code here;                  
     code FAR *next;             
     const unsigned short FAR *base;     
     const unsigned short FAR *extra;    
    int end;                    
     unsigned short count[MAXBITS+1];    
     unsigned short offs[MAXBITS+1];     
     static const unsigned short lbase[31] = { 
        3, 4, 5, 6, 7, 8, 9, 10, 11, 13, 15, 17, 19, 23, 27, 31,
        35, 43, 51, 59, 67, 83, 99, 115, 131, 163, 195, 227, 258, 0, 0};
    static const unsigned short lext[31] = { 
        16, 16, 16, 16, 16, 16, 16, 16, 17, 17, 17, 17, 18, 18, 18, 18,
        19, 19, 19, 19, 20, 20, 20, 20, 21, 21, 21, 21, 16, 203, 198};
    static const unsigned short dbase[32] = { 
        1, 2, 3, 4, 5, 7, 9, 13, 17, 25, 33, 49, 65, 97, 129, 193,
        257, 385, 513, 769, 1025, 1537, 2049, 3073, 4097, 6145,
        8193, 12289, 16385, 24577, 0, 0};
    static const unsigned short dext[32] = { 
        16, 16, 16, 16, 17, 17, 18, 18, 19, 19, 20, 20, 21, 21, 22, 22,
        23, 23, 24, 24, 25, 25, 26, 26, 27, 27,
        28, 28, 29, 29, 64, 64};


    for (len = 0; len <= MAXBITS; len++)
        count[len] = 0;
    for (sym = 0; sym < codes; sym++)
        count[lens[sym]]++;

    root = *bits;
    for (max = MAXBITS; max >= 1; max--)
        if (count[max] != 0) break;
    if (root > max) root = max;
    if (max == 0) {                     
        here.op = (unsigned char)64;    
        here.bits = (unsigned char)1;
        here.val = (unsigned short)0;
        *(*table)++ = here;             
        *(*table)++ = here;
        *bits = 1;
        return 0;     
    }
    for (min = 1; min < max; min++)
        if (count[min] != 0) break;
    if (root < min) root = min;

    left = 1;
    for (len = 1; len <= MAXBITS; len++) {
        left <<= 1;
        left -= count[len];
        if (left < 0) return -1;        
    }
    if (left > 0 && (type == CODES || max != 1))
        return -1;                      

    offs[1] = 0;
    for (len = 1; len < MAXBITS; len++)
        offs[len + 1] = offs[len] + count[len];

    for (sym = 0; sym < codes; sym++)
        if (lens[sym] != 0) work[offs[lens[sym]]++] = (unsigned short)sym;


     switch (type) {
     case CODES:
         base = extra = work;    
        end = 19;
         break;
     case LENS:
         base = lbase;
        base -= 257;
         extra = lext;
        extra -= 257;
        end = 256;
         break;
     default:            
         base = dbase;
         extra = dext;
        end = -1;
     }

    huff = 0;                   
    sym = 0;                    
    len = min;                  
    next = *table;              
    curr = root;                
    drop = 0;                   
    low = (unsigned)(-1);       
    used = 1U << root;          
    mask = used - 1;            

    if ((type == LENS && used > ENOUGH_LENS) ||
        (type == DISTS && used > ENOUGH_DISTS))
        return 1;

     for (;;) {
         here.bits = (unsigned char)(len - drop);
        if ((int)(work[sym]) < end) {
             here.op = (unsigned char)0;
             here.val = work[sym];
         }
        else if ((int)(work[sym]) > end) {
            here.op = (unsigned char)(extra[work[sym]]);
            here.val = base[work[sym]];
         }
         else {
             here.op = (unsigned char)(32 + 64);         
            here.val = 0;
        }

        incr = 1U << (len - drop);
        fill = 1U << curr;
        min = fill;                 
        do {
            fill -= incr;
            next[(huff >> drop) + fill] = here;
        } while (fill != 0);

        incr = 1U << (len - 1);
        while (huff & incr)
            incr >>= 1;
        if (incr != 0) {
            huff &= incr - 1;
            huff += incr;
        }
        else
            huff = 0;

        sym++;
        if (--(count[len]) == 0) {
            if (len == max) break;
            len = lens[work[sym]];
        }

        if (len > root && (huff & mask) != low) {
            if (drop == 0)
                drop = root;

            next += min;            

            curr = len - drop;
            left = (int)(1 << curr);
            while (curr + drop < max) {
                left -= count[curr + drop];
                if (left <= 0) break;
                curr++;
                left <<= 1;
            }

            used += 1U << curr;
            if ((type == LENS && used > ENOUGH_LENS) ||
                (type == DISTS && used > ENOUGH_DISTS))
                return 1;

            low = huff & mask;
            (*table)[low].op = (unsigned char)curr;
            (*table)[low].bits = (unsigned char)root;
            (*table)[low].val = (unsigned short)(next - *table);
        }
    }

    if (huff != 0) {
        here.op = (unsigned char)64;            
        here.bits = (unsigned char)(len - drop);
        here.val = (unsigned short)0;
        next[huff] = here;
    }

    *table += used;
    *bits = root;
    return 0;
}

static int fill_thread_core_info(struct elf_thread_core_info *t,
				 const struct user_regset_view *view,
				 long signr, size_t *total)
{
	unsigned int i;

	fill_prstatus(&t->prstatus, t->task, signr);
	(void) view->regsets[0].get(t->task, &view->regsets[0],
				    0, sizeof(t->prstatus.pr_reg),
				    &t->prstatus.pr_reg, NULL);

	fill_note(&t->notes[0], "CORE", NT_PRSTATUS,
		  sizeof(t->prstatus), &t->prstatus);
	*total += notesize(&t->notes[0]);

	do_thread_regset_writeback(t->task, &view->regsets[0]);

 	for (i = 1; i < view->n; ++i) {
 		const struct user_regset *regset = &view->regsets[i];
 		do_thread_regset_writeback(t->task, regset);
		if (regset->core_note_type &&
 		    (!regset->active || regset->active(t->task, regset))) {
 			int ret;
 			size_t size = regset->n * regset->size;
			void *data = kmalloc(size, GFP_KERNEL);
			if (unlikely(!data))
				return 0;
			ret = regset->get(t->task, regset,
					  0, size, data, NULL);
			if (unlikely(ret))
				kfree(data);
			else {
				if (regset->core_note_type != NT_PRFPREG)
					fill_note(&t->notes[i], "LINUX",
						  regset->core_note_type,
						  size, data);
				else {
					t->prstatus.pr_fpvalid = 1;
					fill_note(&t->notes[i], "CORE",
						  NT_PRFPREG, size, data);
				}
				*total += notesize(&t->notes[i]);
			}
		}
	}

	return 1;
}

