 findoprnd(ITEM *ptr, int32 *pos)
 {
 #ifdef BS_DEBUG
 	elog(DEBUG3, (ptr[*pos].type == OPR) ?
 		 "%d  %c" : "%d  %d", *pos, ptr[*pos].val);
#endif
	if (ptr[*pos].type == VAL)
	{
		ptr[*pos].left = 0;
		(*pos)--;
	}
	else if (ptr[*pos].val == (int32) '!')
	{
		ptr[*pos].left = -1;
		(*pos)--;
		findoprnd(ptr, pos);
	}
	else
	{
		ITEM	   *curitem = &ptr[*pos];
		int32		tmp = *pos;

		(*pos)--;
		findoprnd(ptr, pos);
		curitem->left = *pos - tmp;
		findoprnd(ptr, pos);
	}
}

pam_sm_close_session (pam_handle_t *pamh, int flags UNUSED,
		      int argc, const char **argv)
{
	void *cookiefile;
	int i, debug = 0;
	const char* user;
	struct passwd *tpwd = NULL;
	uid_t unlinkuid, fsuid;

	if (pam_get_user(pamh, &user, NULL) != PAM_SUCCESS)
		pam_syslog(pamh, LOG_ERR, "error determining target user's name");
	else {
	  tpwd = pam_modutil_getpwnam(pamh, user);
	  if (!tpwd)
	    pam_syslog(pamh, LOG_ERR, "error determining target user's UID");
	  else
	    unlinkuid = tpwd->pw_uid;
	}

	for (i = 0; i < argc; i++) {
		if (strcmp(argv[i], "debug") == 0) {
			debug = 1;
			continue;
		}
		if (strncmp(argv[i], "xauthpath=", 10) == 0) {
			continue;
		}
		if (strncmp(argv[i], "systemuser=", 11) == 0) {
			continue;
		}
		if (strncmp(argv[i], "targetuser=", 11) == 0) {
			continue;
		}
		pam_syslog(pamh, LOG_WARNING, "unrecognized option `%s'",
		       argv[i]);
	}

	if (pam_get_data(pamh, DATANAME, (const void**) &cookiefile) == PAM_SUCCESS) {
		if (strlen((char*)cookiefile) > 0) {
			if (debug) {
				pam_syslog(pamh, LOG_DEBUG, "removing `%s'",
				       (char*)cookiefile);
			}
			if (tpwd)
				fsuid = setfsuid(unlinkuid);
			unlink((char*)cookiefile);
			if (tpwd)
				setfsuid(fsuid);
			*((char*)cookiefile) = '\0';
		}
	}
	return PAM_SUCCESS;
}

GBool CachedFileStream::fillBuf()
{
  int n;

  bufPos += bufEnd - buf;
  bufPtr = bufEnd = buf;
  if (limited && bufPos >= start + length) {
    return gFalse;
  }
  if (limited && bufPos + cachedStreamBufSize > start + length) {
    n = start + length - bufPos;
  } else {
    n = cachedStreamBufSize - (bufPos % cachedStreamBufSize);
  }
  cc->read(buf, 1, n);
  bufEnd = buf + n;
  if (bufPtr >= bufEnd) {
    return gFalse;
  }
  return gTrue;
}

