bool AudioHandler::VerifyMixerConnection() {
 PulseAudioMixer::State mixer_state = mixer_->CheckState();
 if (mixer_state == PulseAudioMixer::READY)
    return true;
  if (connected_) {
    connected_ = false;
   LOG(ERROR) << "Lost connection to PulseAudio";
  } else {
    LOG(ERROR) << "Mixer not valid";
  }

 if ((mixer_state == PulseAudioMixer::INITIALIZING) ||
     (mixer_state == PulseAudioMixer::SHUTTING_DOWN))
    return false;

  if (reconnect_tries_ < kMaxReconnectTries) {
    reconnect_tries_++;
   VLOG(1) << "Re-connecting to PulseAudio attempt " << reconnect_tries_ << "/"
            << kMaxReconnectTries;
   mixer_.reset(new PulseAudioMixer());
   connected_ = mixer_->InitSync();
    if (connected_) {
      reconnect_tries_ = 0;
      return true;
    }
   LOG(ERROR) << "Unable to re-connect to PulseAudio";
  }
  return false;
}

static void  Ins_SDPVTL( INS_ARG )
{
  Long  A, B, C;
  Long  p1, p2;   

  p1 = args[1];
  p2 = args[0];

  if ( BOUNDS( p2, CUR.zp1.n_points ) ||
       BOUNDS( p1, CUR.zp2.n_points ) )
  {
    CUR.error = TT_Err_Invalid_Reference;
    return;
  }

  A = CUR.zp1.org_x[p2] - CUR.zp2.org_x[p1];
  B = CUR.zp1.org_y[p2] - CUR.zp2.org_y[p1];

  if ( (CUR.opcode & 1) != 0 )
  {
    C =  B;   
    B =  A;
    A = -C;
  }

  if ( NORMalize( A, B, &CUR.GS.dualVector ) == FAILURE )
    return;

  A = CUR.zp1.cur_x[p2] - CUR.zp2.cur_x[p1];
  B = CUR.zp1.cur_y[p2] - CUR.zp2.cur_y[p1];

  if ( (CUR.opcode & 1) != 0 )
  {
    C =  B;   
    B =  A;
    A = -C;
  }

  if ( NORMalize( A, B, &CUR.GS.projVector ) == FAILURE )
    return;

  COMPUTE_Funcs();
}

