static void  Ins_IUP( INS_ARG )
{
  struct LOC_Ins_IUP  V;
  unsigned char       mask;

  Long first_point;   
  Long end_point;     

  Long first_touched; 
  Long cur_touched;   

  Long point;         
  Long contour;       
  (void)args;

  if ( CUR.opcode & 1 )
  {
    mask   = TT_Flag_Touched_X;
    V.orgs = CUR.pts.org_x;
    V.curs = CUR.pts.cur_x;
  }
  else
  {
    mask   = TT_Flag_Touched_Y;
    V.orgs = CUR.pts.org_y;
    V.curs = CUR.pts.cur_y;
  }

  contour = 0;
  point   = 0;

  do
  {
    end_point   = CUR.pts.contours[contour];
    first_point = point;

    while ( point <= end_point && (CUR.pts.touch[point] & mask) == 0 )
      point++;

    if ( point <= end_point )
    {
      first_touched = point;
      cur_touched   = point;

      point++;

      while ( point <= end_point )
      {
        if ( (CUR.pts.touch[point] & mask) != 0 )
        {
          Interp( (Int)(cur_touched + 1),
                  (Int)(point - 1),
                  (Int)cur_touched,
                  (Int)point,
                  &V );
          cur_touched = point;
        }

        point++;
      }

      if ( cur_touched == first_touched )
        Shift( (Int)first_point, (Int)end_point, (Int)cur_touched, &V );
      else
      {
        Interp((Int)(cur_touched + 1),
               (Int)(end_point),
               (Int)(cur_touched),
               (Int)(first_touched),
               &V );

        Interp((Int)(first_point),
               (Int)(first_touched - 1),
               (Int)(cur_touched),
               (Int)(first_touched),
               &V );
      }
    }
    contour++;
  } while ( contour < CUR.pts.n_contours );
}

static int ldb_match_equality(struct ldb_context *ldb, 
			      const struct ldb_message *msg,
			      const struct ldb_parse_tree *tree,
			      enum ldb_scope scope,
			      bool *matched)
{
	unsigned int i;
	struct ldb_message_element *el;
	const struct ldb_schema_attribute *a;
	struct ldb_dn *valuedn;
	int ret;

	if (ldb_attr_dn(tree->u.equality.attr) == 0) {
		valuedn = ldb_dn_from_ldb_val(ldb, ldb, &tree->u.equality.value);
		if (valuedn == NULL) {
			return LDB_ERR_INVALID_DN_SYNTAX;
		}

		ret = ldb_dn_compare(msg->dn, valuedn);

		talloc_free(valuedn);

		*matched = (ret == 0);
		return LDB_SUCCESS;
	}

	el = ldb_msg_find_element(msg, tree->u.equality.attr);
	if (el == NULL) {
		*matched = false;
		return LDB_SUCCESS;
	}

	a = ldb_schema_attribute_by_name(ldb, el->name);
	if (a == NULL) {
		return LDB_ERR_INVALID_ATTRIBUTE_SYNTAX;
	}

	for (i=0;i<el->num_values;i++) {
		if (a->syntax->operator_fn) {
			ret = a->syntax->operator_fn(ldb, LDB_OP_EQUALITY, a,
						     &tree->u.equality.value, &el->values[i], matched);
			if (ret != LDB_SUCCESS) return ret;
			if (*matched) return LDB_SUCCESS;
		} else {
			if (a->syntax->comparison_fn(ldb, ldb, &tree->u.equality.value,
						     &el->values[i]) == 0) {
				*matched = true;
				return LDB_SUCCESS;
			}
		}
	}

	*matched = false;
	return LDB_SUCCESS;
}

void WebSocketJob::OnSentData(SocketStream* socket, int amount_sent) {
  DCHECK_NE(INITIALIZED, state_);
  if (state_ == CLOSED)
    return;
  if (state_ == CONNECTING) {
    OnSentHandshakeRequest(socket, amount_sent);
    return;
  }
  if (delegate_) {
    DCHECK(state_ == OPEN || state_ == CLOSING);
    DCHECK_GT(amount_sent, 0);
    DCHECK(current_buffer_);
    current_buffer_->DidConsume(amount_sent);
    if (current_buffer_->BytesRemaining() > 0)
      return;

    amount_sent = send_frame_handler_->GetOriginalBufferSize();
     DCHECK_GT(amount_sent, 0);
     current_buffer_ = NULL;
     send_frame_handler_->ReleaseCurrentBuffer();
     delegate_->OnSentData(socket, amount_sent);
    MessageLoopForIO::current()->PostTask(
        FROM_HERE, NewRunnableMethod(this, &WebSocketJob::SendPending));
   }
 }

