static ssize_t read_mem(struct file *file, char __user *buf,
			size_t count, loff_t *ppos)
{
	phys_addr_t p = *ppos;
	ssize_t read, sz;
	void *ptr;

	if (p != *ppos)
		return 0;

	if (!valid_phys_addr_range(p, count))
		return -EFAULT;
	read = 0;
#ifdef __ARCH_HAS_NO_PAGE_ZERO_MAPPED
	if (p < PAGE_SIZE) {
		sz = size_inside_page(p, count);
		if (sz > 0) {
			if (clear_user(buf, sz))
				return -EFAULT;
			buf += sz;
			p += sz;
			count -= sz;
			read += sz;
		}
	}
#endif

 	while (count > 0) {
 		unsigned long remaining;

 		sz = size_inside_page(p, count);

		if (!range_is_allowed(p >> PAGE_SHIFT, count))
 			return -EPERM;

		ptr = xlate_dev_mem_ptr(p);
		if (!ptr)
			return -EFAULT;

		remaining = copy_to_user(buf, ptr, sz);
		unxlate_dev_mem_ptr(p, ptr);
 		if (remaining)
 			return -EFAULT;

		buf += sz;
		p += sz;
		count -= sz;
		read += sz;
	}

	*ppos += read;
	return read;
}

static Bool  Normalize( EXEC_OPS TT_F26Dot6      Vx,
                                 TT_F26Dot6      Vy,
                                 TT_UnitVector*  R )
{
  TT_F26Dot6  W;
  Bool        S1, S2;

  if ( ABS( Vx ) < 0x10000L && ABS( Vy ) < 0x10000L )
  {
    Vx *= 0x100;
    Vy *= 0x100;

    W = Norm( Vx, Vy );

    if ( W == 0 )
    {
      return SUCCESS;
    }

    R->x = (TT_F2Dot14)MulDiv_Round( Vx, 0x4000L, W );
    R->y = (TT_F2Dot14)MulDiv_Round( Vy, 0x4000L, W );

    return SUCCESS;
  }

  W = Norm( Vx, Vy );

  if ( W <= 0 )
  {
    CUR.error = TT_Err_Divide_By_Zero;
    return FAILURE;
  }

  Vx = MulDiv_Round( Vx, 0x4000L, W );
  Vy = MulDiv_Round( Vy, 0x4000L, W );

  W = Vx * Vx + Vy * Vy;


  if ( Vx < 0 )
  {
    Vx = -Vx;
    S1 = TRUE;
  }
  else
    S1 = FALSE;

  if ( Vy < 0 )
  {
    Vy = -Vy;
    S2 = TRUE;
  }
  else
    S2 = FALSE;

  while ( W < 0x10000000L )
  {
    if ( Vx < Vy )
      Vx++;
    else
      Vy++;

    W = Vx * Vx + Vy * Vy;
  }

  while ( W >= 0x10004000L )
  {
    if ( Vx < Vy )
      Vx--;
    else
      Vy--;

    W = Vx * Vx + Vy * Vy;
  }


  if ( S1 )
    Vx = -Vx;

  if ( S2 )
    Vy = -Vy;

  R->x = (TT_F2Dot14)Vx;   
  R->y = (TT_F2Dot14)Vy;   

  return SUCCESS;
}

static NTSTATUS smb1cli_pull_raw_error(const uint8_t *hdr)
{
	uint32_t flags2 = SVAL(hdr, HDR_FLG2);
	NTSTATUS status = NT_STATUS(IVAL(hdr, HDR_RCLS));

	if (NT_STATUS_IS_OK(status)) {
		return NT_STATUS_OK;
	}

	if (flags2 & FLAGS2_32_BIT_ERROR_CODES) {
		return status;
	}

	return NT_STATUS_DOS(CVAL(hdr, HDR_RCLS), SVAL(hdr, HDR_ERR));
}

