void GDataCacheMetadataMap::ScanCacheDirectory(
    const std::vector<FilePath>& cache_paths,
    GDataCache::CacheSubDirectoryType sub_dir_type,
   CacheMap* cache_map,
   ResourceIdToFilePathMap* processed_file_map) {
 DCHECK(cache_map);
 DCHECK(processed_file_map);
  file_util::FileEnumerator enumerator(
      cache_paths[sub_dir_type],
      false,  
     static_cast<file_util::FileEnumerator::FileType>(
         file_util::FileEnumerator::FILES |
         file_util::FileEnumerator::SHOW_SYM_LINKS),
     util::kWildCard);
 for (FilePath current = enumerator.Next(); !current.empty();
      current = enumerator.Next()) {
   std::string resource_id;
   std::string md5;
   std::string extra_extension;
   util::ParseCacheFilePath(current, &resource_id, &md5, &extra_extension);

   int cache_state = GDataCache::CACHE_STATE_NONE;
    if (sub_dir_type == GDataCache::CACHE_TYPE_PINNED) {
     std::string reason;
     if (!IsValidSymbolicLink(current, sub_dir_type, cache_paths, &reason)) {
       LOG(WARNING) << "Removing an invalid symlink: " << current.value()
                    << ": " << reason;
       util::DeleteSymlink(current);
       continue;
     }
      CacheMap::iterator iter = cache_map->find(resource_id);
      if (iter != cache_map->end()) {  
        iter->second.cache_state =
            GDataCache::SetCachePinned(iter->second.cache_state);
       processed_file_map->insert(std::make_pair(resource_id, current));
        continue;
      }
      cache_state = GDataCache::SetCachePinned(cache_state);
    } else if (sub_dir_type == GDataCache::CACHE_TYPE_OUTGOING) {
     std::string reason;
     if (!IsValidSymbolicLink(current, sub_dir_type, cache_paths, &reason)) {
       LOG(WARNING) << "Removing an invalid symlink: " << current.value()
                    << ": " << reason;
       util::DeleteSymlink(current);
       continue;
     }
      CacheMap::iterator iter = cache_map->find(resource_id);
     if (iter == cache_map->end() || !iter->second.IsDirty()) {
       LOG(WARNING) << "Removing an symlink to a non-dirty file: "
                    << current.value();
       util::DeleteSymlink(current);
       continue;
     }
     processed_file_map->insert(std::make_pair(resource_id, current));
     continue;
   } else if (sub_dir_type == GDataCache::CACHE_TYPE_PERSISTENT ||
              sub_dir_type == GDataCache::CACHE_TYPE_TMP) {
     FilePath unused;
     if (file_util::ReadSymbolicLink(current, &unused)) {
       LOG(WARNING) << "Removing a symlink in persistent/tmp directory"
                    << current.value();
       util::DeleteSymlink(current);
       continue;
     }
     if (extra_extension == util::kMountedArchiveFileExtension) {
       DCHECK(sub_dir_type == GDataCache::CACHE_TYPE_PERSISTENT);
       file_util::Delete(current, false);
      } else {
       cache_state = GDataCache::SetCachePresent(cache_state);
       if (md5 == util::kLocallyModifiedFileExtension) {
         if (sub_dir_type == GDataCache::CACHE_TYPE_PERSISTENT) {
           cache_state |= GDataCache::SetCacheDirty(cache_state);
         } else {
           LOG(WARNING) << "Removing a dirty file in tmp directory: "
                        << current.value();
           file_util::Delete(current, false);
           continue;
         }
       }
      }
    } else {
     NOTREACHED() << "Unexpected sub directory type: " << sub_dir_type;
    }

    cache_map->insert(std::make_pair(
        resource_id, GDataCache::CacheEntry(md5, sub_dir_type, cache_state)));
   processed_file_map->insert(std::make_pair(resource_id, current));
  }
}

static int rsa_pss_to_ctx(EVP_MD_CTX *ctx, EVP_PKEY_CTX *pkctx,
                          X509_ALGOR *sigalg, EVP_PKEY *pkey)
{
    int rv = -1;
    int saltlen;
    const EVP_MD *mgf1md = NULL, *md = NULL;
    RSA_PSS_PARAMS *pss;
    X509_ALGOR *maskHash;
    if (OBJ_obj2nid(sigalg->algorithm) != NID_rsassaPss) {
        RSAerr(RSA_F_RSA_PSS_TO_CTX, RSA_R_UNSUPPORTED_SIGNATURE_TYPE);
        return -1;
    }
    pss = rsa_pss_decode(sigalg, &maskHash);

    if (pss == NULL) {
        RSAerr(RSA_F_RSA_PSS_TO_CTX, RSA_R_INVALID_PSS_PARAMETERS);
        goto err;
    }
    mgf1md = rsa_mgf1_to_md(pss->maskGenAlgorithm, maskHash);
    if (!mgf1md)
        goto err;
    md = rsa_algor_to_md(pss->hashAlgorithm);
    if (!md)
        goto err;

    if (pss->saltLength) {
        saltlen = ASN1_INTEGER_get(pss->saltLength);

        if (saltlen < 0) {
            RSAerr(RSA_F_RSA_PSS_TO_CTX, RSA_R_INVALID_SALT_LENGTH);
            goto err;
        }
    } else
        saltlen = 20;

    if (pss->trailerField && ASN1_INTEGER_get(pss->trailerField) != 1) {
        RSAerr(RSA_F_RSA_PSS_TO_CTX, RSA_R_INVALID_TRAILER);
        goto err;
    }


    if (pkey) {
        if (!EVP_DigestVerifyInit(ctx, &pkctx, md, NULL, pkey))
            goto err;
    } else {
        const EVP_MD *checkmd;
        if (EVP_PKEY_CTX_get_signature_md(pkctx, &checkmd) <= 0)
            goto err;
        if (EVP_MD_type(md) != EVP_MD_type(checkmd)) {
            RSAerr(RSA_F_RSA_PSS_TO_CTX, RSA_R_DIGEST_DOES_NOT_MATCH);
            goto err;
        }
    }

    if (EVP_PKEY_CTX_set_rsa_padding(pkctx, RSA_PKCS1_PSS_PADDING) <= 0)
        goto err;

    if (EVP_PKEY_CTX_set_rsa_pss_saltlen(pkctx, saltlen) <= 0)
        goto err;

    if (EVP_PKEY_CTX_set_rsa_mgf1_md(pkctx, mgf1md) <= 0)
        goto err;
    rv = 1;

 err:
    RSA_PSS_PARAMS_free(pss);
    if (maskHash)
        X509_ALGOR_free(maskHash);
    return rv;
}

void NavigationController::NavigateToPendingEntry(ReloadType reload_type) {
  needs_reload_ = false;

  if (pending_entry_index_ != -1 &&
      pending_entry_index_ == last_committed_entry_index_ &&
      (entries_[pending_entry_index_]->restore_type() ==
          NavigationEntry::RESTORE_NONE) &&
       (entries_[pending_entry_index_]->transition_type() &
           content::PAGE_TRANSITION_FORWARD_BACK)) {
     tab_contents_->Stop();
     DiscardNonCommittedEntries();
     return;
   }

   if (!pending_entry_) {
     DCHECK_NE(pending_entry_index_, -1);
    pending_entry_ = entries_[pending_entry_index_].get();
  }

  if (!tab_contents_->NavigateToPendingEntry(reload_type))
    DiscardNonCommittedEntries();

  if (pending_entry_ && !pending_entry_->site_instance() &&
      pending_entry_->restore_type() != NavigationEntry::RESTORE_NONE) {
    pending_entry_->set_site_instance(tab_contents_->GetPendingSiteInstance());
    pending_entry_->set_restore_type(NavigationEntry::RESTORE_NONE);
  }
}

poppler_page_set_selection_alpha (PopplerPage           *page,
				  double                 scale,
				  GdkPixbuf             *pixbuf,
				  PopplerSelectionStyle  style,
				  PopplerRectangle      *selection)
{
  GList *region, *l;
  gint x, y, width, height;
  int pixbuf_rowstride, pixbuf_n_channels;
  guchar *pixbuf_data, *dst;

  pixbuf_data = gdk_pixbuf_get_pixels (pixbuf);
  pixbuf_rowstride = gdk_pixbuf_get_rowstride (pixbuf);
  pixbuf_n_channels = gdk_pixbuf_get_n_channels (pixbuf);
  width = gdk_pixbuf_get_width (pixbuf);
  height = gdk_pixbuf_get_height (pixbuf);

  if (pixbuf_n_channels != 4)
    return;

  for (y = 0; y < height; y++) {
      dst = pixbuf_data + y * pixbuf_rowstride;
      for (x = 0; x < width; x++) {
	  dst[3] = 0x00;
	  dst += pixbuf_n_channels;
      }
  }

  region = poppler_page_get_selection_region (page, scale, style, selection);

  for (l = region; l; l = g_list_next (l)) {
    PopplerRectangle *rectangle = (PopplerRectangle *)l->data;
    GdkRectangle rect;

    rect.x = (gint)rectangle->x1;
    rect.y = (gint)rectangle->y1;
    rect.width  = (gint) (rectangle->x2 - rectangle->x1);
    rect.height = (gint) (rectangle->y2 - rectangle->y1);

    for (y = 0; y < rect.height; y++) {
      dst = pixbuf_data + (rect.y + y) * pixbuf_rowstride +
	rect.x * pixbuf_n_channels;
      for (x = 0; x < rect.width; x++) {
	  dst[3] = 0xff;
	  dst += pixbuf_n_channels;
      }
    }
  }

  poppler_page_selection_region_free (region);
}

