bdf_load_font( FT_Stream       stream,
               FT_Memory       extmemory,
               bdf_options_t*  opts,
               bdf_font_t*    *font )
{
  unsigned long  lineno = 0; 
  _bdf_parse_t   *p     = NULL;

  FT_Memory      memory = extmemory;
  FT_Error       error  = BDF_Err_Ok;


  if ( FT_NEW( p ) )
    goto Exit;

  memory    = NULL;
  p->opts   = (bdf_options_t*)( ( opts != 0 ) ? opts : &_bdf_opts );
  p->minlb  = 32767;
  p->memory = extmemory;  

  _bdf_list_init( &p->list, extmemory );

  error = _bdf_readstream( stream, _bdf_parse_start,
                           (void *)p, &lineno );
  if ( error )
    goto Fail;

  if ( p->font != 0 )
  {
    memory = p->font->memory;

    if ( p->font->spacing != BDF_PROPORTIONAL )
      p->font->monowidth = p->font->bbx.width;

    if ( p->cnt != p->font->glyphs_used + p->font->unencoded_used )
    {
      FT_TRACE2(( "bdf_load_font: " ACMSG15, p->cnt,
                  p->font->glyphs_used + p->font->unencoded_used ));
      p->font->modified = 1;
    }

    if ( p->opts->correct_metrics != 0 &&
         ( p->font->glyphs_used > 0 || p->font->unencoded_used > 0 ) )
    {
      if ( p->maxrb - p->minlb != p->font->bbx.width )
      {
        FT_TRACE2(( "bdf_load_font: " ACMSG3,
                    p->font->bbx.width, p->maxrb - p->minlb ));
        p->font->bbx.width = (unsigned short)( p->maxrb - p->minlb );
        p->font->modified  = 1;
      }

      if ( p->font->bbx.x_offset != p->minlb )
      {
        FT_TRACE2(( "bdf_load_font: " ACMSG4,
                    p->font->bbx.x_offset, p->minlb ));
        p->font->bbx.x_offset = p->minlb;
        p->font->modified     = 1;
      }

      if ( p->font->bbx.ascent != p->maxas )
      {
        FT_TRACE2(( "bdf_load_font: " ACMSG5,
                    p->font->bbx.ascent, p->maxas ));
        p->font->bbx.ascent = p->maxas;
        p->font->modified   = 1;
      }

      if ( p->font->bbx.descent != p->maxds )
      {
        FT_TRACE2(( "bdf_load_font: " ACMSG6,
                    p->font->bbx.descent, p->maxds ));
        p->font->bbx.descent  = p->maxds;
        p->font->bbx.y_offset = (short)( -p->maxds );
        p->font->modified     = 1;
      }

      if ( p->maxas + p->maxds != p->font->bbx.height )
      {
        FT_TRACE2(( "bdf_load_font: " ACMSG7,
                    p->font->bbx.height, p->maxas + p->maxds ));
        p->font->bbx.height = (unsigned short)( p->maxas + p->maxds );
      }

      if ( p->flags & _BDF_SWIDTH_ADJ )
        FT_TRACE2(( "bdf_load_font: " ACMSG8 ));
    }
  }

  if ( p->flags & _BDF_START )
  {
    if ( !( p->flags & _BDF_GLYPHS ) )
    {
      FT_ERROR(( "bdf_load_font: " ERRMSG2, lineno ));
      error = BDF_Err_Corrupted_Font_Header;
      goto Exit;
    }
    else
    {
      FT_ERROR(( "bdf_load_font: " ERRMSG3, lineno ));
      error = BDF_Err_Corrupted_Font_Glyphs;
      goto Exit;
    }
  }

  if ( p->font != 0 )
  {
    memory = p->font->memory;

    if ( p->font->comments_len > 0 )
    {
      if ( FT_RENEW_ARRAY( p->font->comments,
                           p->font->comments_len,
                           p->font->comments_len + 1 ) )
        goto Fail;

      p->font->comments[p->font->comments_len] = 0;
    }
  }
  else if ( error == BDF_Err_Ok )
    error = BDF_Err_Invalid_File_Format;

  *font = p->font;

Exit:
  if ( p )
  {
    _bdf_list_done( &p->list );

    memory = extmemory;

    FT_FREE( p );
  }

  return error;

Fail:
  bdf_free_font( p->font );

  memory = extmemory;

  FT_FREE( p->font );

  goto Exit;
}

int parse_csum_name(const char *name, int len)
{
	if (len < 0 && name)
		len = strlen(name);

	if (!name || (len == 4 && strncasecmp(name, "auto", 4) == 0)) {
		if (protocol_version >= 30)
			return CSUM_MD5;
		if (protocol_version >= 27)
			return CSUM_MD4_OLD;
		if (protocol_version >= 21)
			return CSUM_MD4_BUSTED;
		return CSUM_MD4_ARCHAIC;
	}
	if (len == 3 && strncasecmp(name, "md4", 3) == 0)
		return CSUM_MD4;
	if (len == 3 && strncasecmp(name, "md5", 3) == 0)
		return CSUM_MD5;
	if (len == 4 && strncasecmp(name, "none", 4) == 0)
		return CSUM_NONE;

	rprintf(FERROR, "unknown checksum name: %s\n", name);
	exit_cleanup(RERR_UNSUPPORTED);
}

void ChromotingHost::Start() {
  if (!context_->network_message_loop()->BelongsToCurrentThread()) {
    context_->network_message_loop()->PostTask(
        FROM_HERE, base::Bind(&ChromotingHost::Start, this));
    return;
  }

  LOG(INFO) << "Starting host";
  DCHECK(!signal_strategy_.get());
   DCHECK(access_verifier_.get());

  {
    base::AutoLock auto_lock(lock_);
    if (state_ != kInitial)
      return;
    state_ = kStarted;
  }

   std::string xmpp_login;
  std::string xmpp_auth_token;
  std::string xmpp_auth_service;
  if (!config_->GetString(kXmppLoginConfigPath, &xmpp_login) ||
      !config_->GetString(kXmppAuthTokenConfigPath, &xmpp_auth_token) ||
      !config_->GetString(kXmppAuthServiceConfigPath, &xmpp_auth_service)) {
    LOG(ERROR) << "XMPP credentials are not defined in the config.";
    return;
  }

  signal_strategy_.reset(
      new XmppSignalStrategy(context_->jingle_thread(), xmpp_login,
                             xmpp_auth_token,
                             xmpp_auth_service));
  signal_strategy_->Init(this);
}

pdf14_push_transparency_group(pdf14_ctx	*ctx, gs_int_rect *rect, bool isolated,
                              bool knockout, byte alpha, byte shape,
                              gs_blend_mode_t blend_mode, bool idle, uint mask_id,
                              int numcomps, bool cm_back_drop,
                              cmm_profile_t *group_profile,
                              cmm_profile_t *tos_profile, gs_gstate *pgs,
                              gx_device *dev)
{
    pdf14_buf *tos = ctx->stack;
    pdf14_buf *buf, *backdrop;
    bool has_shape, has_tags;

    if_debug1m('v', ctx->memory,
               "[v]pdf14_push_transparency_group, idle = %d\n", idle);

    has_shape = tos->has_shape || tos->knockout;
    has_tags = tos->has_tags;

    buf = pdf14_buf_new(rect, has_tags, !isolated, has_shape, idle, numcomps + 1,
                        tos->num_spots, ctx->memory);
    if (buf == NULL)
        return_error(gs_error_VMerror);
    if_debug4m('v', ctx->memory,
        "[v]base buf: %d x %d, %d color channels, %d planes\n",
        buf->rect.q.x, buf->rect.q.y, buf->n_chan, buf->n_planes);
    buf->isolated = isolated;
    buf->knockout = knockout;
    buf->alpha = alpha;
    buf->shape = shape;
    buf->blend_mode = blend_mode;
    buf->mask_id = mask_id;
    buf->mask_stack = ctx->mask_stack; 
    ctx->mask_stack = NULL; 
    buf->saved = tos;
    ctx->stack = buf;
    if (buf->data == NULL)
        return 0;
    if (idle)
        return 0;
    backdrop = pdf14_find_backdrop_buf(ctx);
    if (backdrop == NULL) {
        memset(buf->data, 0, buf->planestride * (buf->n_chan +
                                                 (buf->has_shape ? 1 : 0) +
                                                 (buf->has_alpha_g ? 1 : 0)));
    } else {
        if (!buf->knockout) {
            if (!cm_back_drop) {
                pdf14_preserve_backdrop(buf, tos, false);
            } else {
                pdf14_preserve_backdrop_cm(buf, group_profile, tos, tos_profile,
                                           ctx->memory, pgs, dev, false);
            }
        }
    }

    if (buf->knockout) {
        buf->backdrop = gs_alloc_bytes(ctx->memory, buf->planestride * buf->n_chan,
                                        "pdf14_push_transparency_group");
        if (buf->backdrop == NULL) {
            return gs_throw(gs_error_VMerror, "Knockout backdrop allocation failed");
        }
        if (buf->isolated) {
            memset(buf->backdrop, 0, buf->planestride * buf->n_chan);
        } else {
            pdf14_buf *check = tos;
            pdf14_buf *child = NULL;  
            cmm_profile_t *prev_knockout_profile;

            while (check != NULL) {
                if (check->isolated)
                    break;
                if (check->knockout) {
                    break;
                }
                child = check;
                check = check->saved;
            }
            if (check == NULL) {
                prev_knockout_profile = tos_profile;
                check = tos;
            } else {
                if (child == NULL) {
                    prev_knockout_profile = tos_profile;
                } else {
                    prev_knockout_profile  = child->parent_color_info_procs->icc_profile;
                }
            }
            if (!cm_back_drop) {
                pdf14_preserve_backdrop(buf, check, false);
            } else {
                pdf14_preserve_backdrop_cm(buf, group_profile, check,
                                           prev_knockout_profile, ctx->memory, pgs,
                                           dev, false);
            }
            memcpy(buf->backdrop, buf->data, buf->planestride * buf->n_chan);
        }
#if RAW_DUMP
        dump_raw_buffer(ctx->stack->rect.q.y-ctx->stack->rect.p.y,
                    ctx->stack->rowstride, buf->n_chan,
                    ctx->stack->planestride, ctx->stack->rowstride,
                    "KnockoutBackDrop", buf->backdrop);
        global_index++;
#endif
    } else {
        buf->backdrop = NULL;
    }
#if RAW_DUMP
    dump_raw_buffer(ctx->stack->rect.q.y-ctx->stack->rect.p.y,
                ctx->stack->rowstride, ctx->stack->n_planes,
                ctx->stack->planestride, ctx->stack->rowstride,
                "TransGroupPush", ctx->stack->data);
    global_index++;
#endif
    return 0;
}

