logger_get_mask_expanded (struct t_gui_buffer *buffer, const char *mask)
{
   char *mask2, *mask_decoded, *mask_decoded2, *mask_decoded3, *mask_decoded4;
   char *mask_decoded5;
    const char *dir_separator;
    int length;
    time_t seconds;
    struct tm *date_tmp;

    mask2 = NULL;
   mask_decoded = NULL;
   mask_decoded2 = NULL;
   mask_decoded3 = NULL;
   mask_decoded4 = NULL;
   mask_decoded5 = NULL;

    dir_separator = weechat_info_get ("dir_separator", "");
    if (!dir_separator)
        return NULL;

   mask2 = weechat_string_replace (mask, dir_separator, "\01");
   if (!mask2)
        goto end;

   mask_decoded = weechat_buffer_string_replace_local_var (buffer, mask2);
   if (!mask_decoded)
        goto end;

   mask_decoded2 = weechat_string_replace (mask_decoded,
                                           dir_separator,
                                           weechat_config_string (logger_config_file_replacement_char));
   if (!mask_decoded2)
        goto end;

#ifdef __CYGWIN__
   mask_decoded3 = weechat_string_replace (mask_decoded2, "\\",
                                           weechat_config_string (logger_config_file_replacement_char));
#else
   mask_decoded3 = strdup (mask_decoded2);
#endif 
   if (!mask_decoded3)
        goto end;

   mask_decoded4 = weechat_string_replace (mask_decoded3,
                                           "\01", dir_separator);
   if (!mask_decoded4)
       goto end;
   length = strlen (mask_decoded4) + 256 + 1;
   mask_decoded5 = malloc (length);
   if (!mask_decoded5)
        goto end;
   seconds = time (NULL);
   date_tmp = localtime (&seconds);
   mask_decoded5[0] = '\0';
   strftime (mask_decoded5, length - 1, mask_decoded4, date_tmp);

    if (weechat_config_boolean (logger_config_file_name_lower_case))
       weechat_string_tolower (mask_decoded5);

    if (weechat_logger_plugin->debug)
    {
       weechat_printf_date_tags (NULL, 0, "no_log",
                                 "%s: buffer = \"%s\", mask = \"%s\", "
                                  "decoded mask = \"%s\"",
                                  LOGGER_PLUGIN_NAME,
                                  weechat_buffer_get_string (buffer, "name"),
                                 mask, mask_decoded5);
    }

end:
    if (mask2)
        free (mask2);
   if (mask_decoded)
       free (mask_decoded);
   if (mask_decoded2)
       free (mask_decoded2);
   if (mask_decoded3)
       free (mask_decoded3);
   if (mask_decoded4)
       free (mask_decoded4);
   return mask_decoded5;
}

 void OomInterventionImpl::Check(TimerBase*) {
   DCHECK(host_);

   OomInterventionMetrics current_memory = GetCurrentMemoryMetrics();
   bool oom_detected = false;

  oom_detected |= detection_args_->blink_workload_threshold > 0 &&
                  current_memory.current_blink_usage_kb * 1024 >
                      detection_args_->blink_workload_threshold;
  oom_detected |= detection_args_->private_footprint_threshold > 0 &&
                  current_memory.current_private_footprint_kb * 1024 >
                      detection_args_->private_footprint_threshold;
  oom_detected |=
      detection_args_->swap_threshold > 0 &&
      current_memory.current_swap_kb * 1024 > detection_args_->swap_threshold;
  oom_detected |= detection_args_->virtual_memory_thresold > 0 &&
                  current_memory.current_vm_size_kb * 1024 >
                      detection_args_->virtual_memory_thresold;

  ReportMemoryStats(current_memory);

  if (oom_detected) {
    if (navigate_ads_enabled_) {
      for (const auto& page : Page::OrdinaryPages()) {
        if (page->MainFrame()->IsLocalFrame()) {
          ToLocalFrame(page->MainFrame())
              ->GetDocument()
              ->NavigateLocalAdsFrames();
        }
      }
    }

    if (renderer_pause_enabled_) {
      pauser_.reset(new ScopedPagePauser);
    }
    host_->OnHighMemoryUsage();
    timer_.Stop();
    V8GCForContextDispose::Instance().SetForcePageNavigationGC();
  }
}

void ChromeContentRendererClient::RenderThreadStarted() {
  chrome_observer_.reset(new ChromeRenderProcessObserver());
  extension_dispatcher_.reset(new ExtensionDispatcher());
  histogram_snapshots_.reset(new RendererHistogramSnapshots());
  net_predictor_.reset(new RendererNetPredictor());
  spellcheck_.reset(new SpellCheck());
  visited_link_slave_.reset(new VisitedLinkSlave());
#if defined(ENABLE_SAFE_BROWSING)
  phishing_classifier_.reset(safe_browsing::PhishingClassifierFilter::Create());
 #endif

   RenderThread* thread = RenderThread::current();
  thread->AddFilter(new DevToolsAgentFilter());

   thread->AddObserver(chrome_observer_.get());
   thread->AddObserver(extension_dispatcher_.get());
  thread->AddObserver(histogram_snapshots_.get());
#if defined(ENABLE_SAFE_BROWSING)
  thread->AddObserver(phishing_classifier_.get());
#endif
  thread->AddObserver(spellcheck_.get());
  thread->AddObserver(visited_link_slave_.get());

  thread->RegisterExtension(extensions_v8::ExternalExtension::Get());
  thread->RegisterExtension(extensions_v8::LoadTimesExtension::Get());
  thread->RegisterExtension(extensions_v8::SearchBoxExtension::Get());
  v8::Extension* search_extension = extensions_v8::SearchExtension::Get();
  if (search_extension)
    thread->RegisterExtension(search_extension);

  if (CommandLine::ForCurrentProcess()->HasSwitch(
          switches::kDomAutomationController)) {
    thread->RegisterExtension(DomAutomationV8Extension::Get());
  }

  if (CommandLine::ForCurrentProcess()->HasSwitch(
          switches::kEnableIPCFuzzing)) {
    thread->channel()->set_outgoing_message_filter(LoadExternalIPCFuzzer());
  }
  WebString chrome_ui_scheme(ASCIIToUTF16(chrome::kChromeUIScheme));
  WebSecurityPolicy::registerURLSchemeAsDisplayIsolated(chrome_ui_scheme);

  WebString dev_tools_scheme(ASCIIToUTF16(chrome::kChromeDevToolsScheme));
  WebSecurityPolicy::registerURLSchemeAsDisplayIsolated(dev_tools_scheme);

  WebString internal_scheme(ASCIIToUTF16(chrome::kChromeInternalScheme));
  WebSecurityPolicy::registerURLSchemeAsDisplayIsolated(internal_scheme);

  WebString extension_scheme(ASCIIToUTF16(chrome::kExtensionScheme));
  WebSecurityPolicy::registerURLSchemeAsSecure(extension_scheme);
}

