SYSCALL_DEFINE5(perf_event_open,
		struct perf_event_attr __user *, attr_uptr,
		pid_t, pid, int, cpu, int, group_fd, unsigned long, flags)
{
 	struct perf_event *group_leader = NULL, *output_event = NULL;
 	struct perf_event *event, *sibling;
 	struct perf_event_attr attr;
	struct perf_event_context *ctx;
 	struct file *event_file = NULL;
 	struct fd group = {NULL, 0};
 	struct task_struct *task = NULL;
	struct pmu *pmu;
	int event_fd;
	int move_group = 0;
	int err;
	int f_flags = O_RDWR;

	if (flags & ~PERF_FLAG_ALL)
		return -EINVAL;

	err = perf_copy_attr(attr_uptr, &attr);
	if (err)
		return err;

	if (!attr.exclude_kernel) {
		if (perf_paranoid_kernel() && !capable(CAP_SYS_ADMIN))
			return -EACCES;
	}

	if (attr.freq) {
		if (attr.sample_freq > sysctl_perf_event_sample_rate)
			return -EINVAL;
	} else {
		if (attr.sample_period & (1ULL << 63))
			return -EINVAL;
	}

	if ((flags & PERF_FLAG_PID_CGROUP) && (pid == -1 || cpu == -1))
		return -EINVAL;

	if (flags & PERF_FLAG_FD_CLOEXEC)
		f_flags |= O_CLOEXEC;

	event_fd = get_unused_fd_flags(f_flags);
	if (event_fd < 0)
		return event_fd;

	if (group_fd != -1) {
		err = perf_fget_light(group_fd, &group);
		if (err)
			goto err_fd;
		group_leader = group.file->private_data;
		if (flags & PERF_FLAG_FD_OUTPUT)
			output_event = group_leader;
		if (flags & PERF_FLAG_FD_NO_GROUP)
			group_leader = NULL;
	}

	if (pid != -1 && !(flags & PERF_FLAG_PID_CGROUP)) {
		task = find_lively_task_by_vpid(pid);
		if (IS_ERR(task)) {
			err = PTR_ERR(task);
			goto err_group_fd;
		}
	}

	if (task && group_leader &&
	    group_leader->attr.inherit != attr.inherit) {
		err = -EINVAL;
		goto err_task;
	}

	get_online_cpus();

	event = perf_event_alloc(&attr, cpu, task, group_leader, NULL,
				 NULL, NULL);
	if (IS_ERR(event)) {
		err = PTR_ERR(event);
		goto err_cpus;
	}

	if (flags & PERF_FLAG_PID_CGROUP) {
		err = perf_cgroup_connect(pid, event, &attr, group_leader);
		if (err) {
			__free_event(event);
			goto err_cpus;
		}
	}

	if (is_sampling_event(event)) {
		if (event->pmu->capabilities & PERF_PMU_CAP_NO_INTERRUPT) {
			err = -ENOTSUPP;
			goto err_alloc;
		}
	}

	account_event(event);

	pmu = event->pmu;

	if (group_leader &&
	    (is_software_event(event) != is_software_event(group_leader))) {
		if (is_software_event(event)) {
			pmu = group_leader->pmu;
		} else if (is_software_event(group_leader) &&
			   (group_leader->group_flags & PERF_GROUP_SOFTWARE)) {
			move_group = 1;
		}
	}

	ctx = find_get_context(pmu, task, event->cpu);
	if (IS_ERR(ctx)) {
		err = PTR_ERR(ctx);
		goto err_alloc;
	}

	if (task) {
		put_task_struct(task);
		task = NULL;
	}

	if (group_leader) {
		err = -EINVAL;

		if (group_leader->group_leader != group_leader)
			goto err_context;
		if (move_group) {
			if (group_leader->ctx->task != ctx->task)
				goto err_context;

			if (group_leader->cpu != event->cpu)
				goto err_context;
		} else {
			if (group_leader->ctx != ctx)
				goto err_context;
		}

		if (attr.exclusive || attr.pinned)
			goto err_context;
	}

	if (output_event) {
		err = perf_event_set_output(event, output_event);
		if (err)
			goto err_context;
	}

	event_file = anon_inode_getfile("[perf_event]", &perf_fops, event,
					f_flags);
	if (IS_ERR(event_file)) {
		err = PTR_ERR(event_file);
		goto err_context;
 	}

 	if (move_group) {
		struct perf_event_context *gctx = group_leader->ctx;

		mutex_lock(&gctx->mutex);
 		perf_remove_from_context(group_leader, false);

		perf_event__state_init(group_leader);
		list_for_each_entry(sibling, &group_leader->sibling_list,
				    group_entry) {
			perf_remove_from_context(sibling, false);
 			perf_event__state_init(sibling);
 			put_ctx(gctx);
 		}
		mutex_unlock(&gctx->mutex);
		put_ctx(gctx);
 	}

 	WARN_ON_ONCE(ctx->parent_ctx);
	mutex_lock(&ctx->mutex);

 	if (move_group) {
 		synchronize_rcu();
 		perf_install_in_context(ctx, group_leader, group_leader->cpu);
 		get_ctx(ctx);
 		list_for_each_entry(sibling, &group_leader->sibling_list,
				    group_entry) {
			perf_install_in_context(ctx, sibling, sibling->cpu);
			get_ctx(ctx);
		}
	}

 	perf_install_in_context(ctx, event, event->cpu);
 	perf_unpin_context(ctx);
 	mutex_unlock(&ctx->mutex);

 	put_online_cpus();

	event->owner = current;

	mutex_lock(&current->perf_event_mutex);
	list_add_tail(&event->owner_entry, &current->perf_event_list);
	mutex_unlock(&current->perf_event_mutex);

	perf_event__header_size(event);
	perf_event__id_header_size(event);

	fdput(group);
	fd_install(event_fd, event_file);
	return event_fd;

err_context:
	perf_unpin_context(ctx);
	put_ctx(ctx);
err_alloc:
	free_event(event);
err_cpus:
	put_online_cpus();
err_task:
	if (task)
		put_task_struct(task);
err_group_fd:
	fdput(group);
err_fd:
	put_unused_fd(event_fd);
	return err;
}

_bdf_parse_glyphs( char*          line,
                   unsigned long  linelen,
                   unsigned long  lineno,
                   void*          call_data,
                   void*          client_data )
{
  int                c, mask_index;
  char*              s;
  unsigned char*     bp;
  unsigned long      i, slen, nibbles;

  _bdf_parse_t*      p;
  bdf_glyph_t*       glyph;
  bdf_font_t*        font;

  FT_Memory          memory;
  FT_Error           error = BDF_Err_Ok;

  FT_UNUSED( call_data );
  FT_UNUSED( lineno );        


  p = (_bdf_parse_t *)client_data;

  font   = p->font;
  memory = font->memory;

  if ( ft_memcmp( line, "COMMENT", 7 ) == 0 )
  {
    linelen -= 7;

    s = line + 7;
    if ( *s != 0 )
    {
      s++;
      linelen--;
    }
    error = _bdf_add_comment( p->font, s, linelen );
    goto Exit;
  }

  if ( !( p->flags & _BDF_GLYPHS ) )
  {
    if ( ft_memcmp( line, "CHARS", 5 ) != 0 )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "CHARS" ));
      error = BDF_Err_Missing_Chars_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;
    p->cnt = font->glyphs_size = _bdf_atoul( p->list.field[1], 0, 10 );

    if ( p->cnt == 0 )
      font->glyphs_size = 64;

    if ( p->cnt >= 0x110000UL )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "CHARS" ));
      error = BDF_Err_Invalid_Argument;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( font->glyphs, font->glyphs_size ) )
      goto Exit;

    p->flags |= _BDF_GLYPHS;

    goto Exit;
  }

  if ( ft_memcmp( line, "ENDFONT", 7 ) == 0 )
  {
    ft_qsort( (char *)font->glyphs,
              font->glyphs_used,
              sizeof ( bdf_glyph_t ),
              by_encoding );

    p->flags &= ~_BDF_START;

    goto Exit;
  }

  if ( ft_memcmp( line, "ENDCHAR", 7 ) == 0 )
  {
    p->glyph_enc = 0;
    p->flags    &= ~_BDF_GLYPH_BITS;

    goto Exit;
  }

  if ( ( p->flags & _BDF_GLYPH )     &&
       p->glyph_enc            == -1 &&
       p->opts->keep_unencoded == 0  )
    goto Exit;

  if ( ft_memcmp( line, "STARTCHAR", 9 ) == 0 )
  {
    FT_FREE( p->glyph_name );

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    _bdf_list_shift( &p->list, 1 );

    s = _bdf_list_join( &p->list, ' ', &slen );

    if ( !s )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG8, lineno, "STARTCHAR" ));
      error = BDF_Err_Invalid_File_Format;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( p->glyph_name, slen + 1 ) )
      goto Exit;

    FT_MEM_COPY( p->glyph_name, s, slen + 1 );

    p->flags |= _BDF_GLYPH;

    FT_TRACE4(( DBGMSG1, lineno, s ));

    goto Exit;
  }

  if ( ft_memcmp( line, "ENCODING", 8 ) == 0 )
  {
    if ( !( p->flags & _BDF_GLYPH ) )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "STARTCHAR" ));
      error = BDF_Err_Missing_Startchar_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    p->glyph_enc = _bdf_atol( p->list.field[1], 0, 10 );

    if ( p->glyph_enc < -1 )
      p->glyph_enc = -1;

    if ( p->glyph_enc == -1 && p->list.used > 2 )
      p->glyph_enc = _bdf_atol( p->list.field[2], 0, 10 );

    FT_TRACE4(( DBGMSG2, p->glyph_enc ));

    if ( p->glyph_enc > 0                               &&
         (size_t)p->glyph_enc >= sizeof ( p->have ) * 8 )
     {
       FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "ENCODING" ));
       error = BDF_Err_Invalid_File_Format;
    }

    if ( p->glyph_enc >= 0 )
    {
      if ( _bdf_glyph_modified( p->have, p->glyph_enc ) )
      {
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG12,
                    p->glyph_enc, p->glyph_name ));
        p->glyph_enc = -1;
        font->modified = 1;
      }
      else
        _bdf_set_glyph_modified( p->have, p->glyph_enc );
    }

    if ( p->glyph_enc >= 0 )
    {
      if ( font->glyphs_used == font->glyphs_size )
      {
        if ( FT_RENEW_ARRAY( font->glyphs,
                             font->glyphs_size,
                             font->glyphs_size + 64 ) )
          goto Exit;

        font->glyphs_size += 64;
      }

      glyph           = font->glyphs + font->glyphs_used++;
      glyph->name     = p->glyph_name;
      glyph->encoding = p->glyph_enc;

      p->glyph_name = 0;
    }
    else
    {
      if ( p->opts->keep_unencoded != 0 )
      {
        if ( font->unencoded_used == font->unencoded_size )
        {
          if ( FT_RENEW_ARRAY( font->unencoded ,
                               font->unencoded_size,
                               font->unencoded_size + 4 ) )
            goto Exit;

          font->unencoded_size += 4;
        }

        glyph           = font->unencoded + font->unencoded_used;
        glyph->name     = p->glyph_name;
        glyph->encoding = font->unencoded_used++;
      }
      else
        FT_FREE( p->glyph_name );

      p->glyph_name = 0;
    }

    p->flags &= ~( _BDF_GLYPH_WIDTH_CHECK | _BDF_GLYPH_HEIGHT_CHECK );

    p->flags |= _BDF_ENCODING;

    goto Exit;
  }

  if ( p->glyph_enc == -1 )
    glyph = font->unencoded + ( font->unencoded_used - 1 );
  else
    glyph = font->glyphs + ( font->glyphs_used - 1 );

  if ( p->flags & _BDF_BITMAP )
  {
    if ( p->row >= (unsigned long)glyph->bbx.height )
    {
      if ( !( p->flags & _BDF_GLYPH_HEIGHT_CHECK ) )
      {
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG13, glyph->encoding ));
        p->flags |= _BDF_GLYPH_HEIGHT_CHECK;
        font->modified = 1;
      }

      goto Exit;
    }

    nibbles = glyph->bpr << 1;
    bp      = glyph->bitmap + p->row * glyph->bpr;

    for ( i = 0; i < nibbles; i++ )
    {
      c = line[i];
      if ( !sbitset( hdigits, c ) )
        break;
      *bp = (FT_Byte)( ( *bp << 4 ) + a2i[c] );
      if ( i + 1 < nibbles && ( i & 1 ) )
        *++bp = 0;
    }

    if ( i < nibbles                            &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG16, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    mask_index = ( glyph->bbx.width * p->font->bpp ) & 7;
    if ( glyph->bbx.width )
      *bp &= nibble_mask[mask_index];

    if ( i == nibbles                           &&
         sbitset( hdigits, line[nibbles] )      &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG14, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    p->row++;
    goto Exit;
  }

  if ( ft_memcmp( line, "SWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->swidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );
    p->flags |= _BDF_SWIDTH;

    goto Exit;
  }

  if ( ft_memcmp( line, "DWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->dwidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );

    if ( !( p->flags & _BDF_SWIDTH ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG9, lineno ));

      glyph->swidth = (unsigned short)FT_MulDiv(
                        glyph->dwidth, 72000L,
                        (FT_Long)( font->point_size *
                                   font->resolution_x ) );
    }

    p->flags |= _BDF_DWIDTH;
    goto Exit;
  }

  if ( ft_memcmp( line, "BBX", 3 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->bbx.width    = _bdf_atos( p->list.field[1], 0, 10 );
    glyph->bbx.height   = _bdf_atos( p->list.field[2], 0, 10 );
    glyph->bbx.x_offset = _bdf_atos( p->list.field[3], 0, 10 );
    glyph->bbx.y_offset = _bdf_atos( p->list.field[4], 0, 10 );

    glyph->bbx.ascent  = (short)( glyph->bbx.height + glyph->bbx.y_offset );
    glyph->bbx.descent = (short)( -glyph->bbx.y_offset );

    p->maxas    = (short)FT_MAX( glyph->bbx.ascent, p->maxas );
    p->maxds    = (short)FT_MAX( glyph->bbx.descent, p->maxds );

    p->rbearing = (short)( glyph->bbx.width + glyph->bbx.x_offset );

    p->maxrb    = (short)FT_MAX( p->rbearing, p->maxrb );
    p->minlb    = (short)FT_MIN( glyph->bbx.x_offset, p->minlb );
    p->maxlb    = (short)FT_MAX( glyph->bbx.x_offset, p->maxlb );

    if ( !( p->flags & _BDF_DWIDTH ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG10, lineno ));
      glyph->dwidth = glyph->bbx.width;
    }

    if ( p->opts->correct_metrics != 0 )
    {
      unsigned short  sw = (unsigned short)FT_MulDiv(
                             glyph->dwidth, 72000L,
                             (FT_Long)( font->point_size *
                                        font->resolution_x ) );


      if ( sw != glyph->swidth )
      {
        glyph->swidth = sw;

        if ( p->glyph_enc == -1 )
          _bdf_set_glyph_modified( font->umod,
                                   font->unencoded_used - 1 );
        else
          _bdf_set_glyph_modified( font->nmod, glyph->encoding );

        p->flags       |= _BDF_SWIDTH_ADJ;
        font->modified  = 1;
      }
    }

    p->flags |= _BDF_BBX;
    goto Exit;
  }

  if ( ft_memcmp( line, "BITMAP", 6 ) == 0 )
  {
    unsigned long  bitmap_size;


    if ( !( p->flags & _BDF_BBX ) )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "BBX" ));
      error = BDF_Err_Missing_Bbx_Field;
      goto Exit;
    }

    glyph->bpr = ( glyph->bbx.width * p->font->bpp + 7 ) >> 3;

    bitmap_size = glyph->bpr * glyph->bbx.height;
    if ( glyph->bpr > 0xFFFFU || bitmap_size > 0xFFFFU )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG4, lineno ));
      error = BDF_Err_Bbx_Too_Big;
      goto Exit;
    }
    else
      glyph->bytes = (unsigned short)bitmap_size;

    if ( FT_NEW_ARRAY( glyph->bitmap, glyph->bytes ) )
      goto Exit;

    p->row    = 0;
    p->flags |= _BDF_BITMAP;

    goto Exit;
  }

  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG9, lineno ));
  error = BDF_Err_Invalid_File_Format;
  goto Exit;

Missing_Encoding:
  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "ENCODING" ));
  error = BDF_Err_Missing_Encoding_Field;

Exit:
  if ( error && ( p->flags & _BDF_GLYPH ) )
    FT_FREE( p->glyph_name );

  return error;
}

PS_SERIALIZER_DECODE_FUNC(php_binary) 
{
	const char *p;
	char *name;
	const char *endptr = val + vallen;
	zval *current;
	int namelen;
	int has_value;
	php_unserialize_data_t var_hash;

	PHP_VAR_UNSERIALIZE_INIT(var_hash);

	for (p = val; p < endptr; ) {
		zval **tmp;
                namelen = ((unsigned char)(*p)) & (~PS_BIN_UNDEF);

                if (namelen < 0 || namelen > PS_BIN_MAX || (p + namelen) >= endptr) {
                        return FAILURE;
                }

		name = estrndup(p + 1, namelen);

		p += namelen + 1;

		if (zend_hash_find(&EG(symbol_table), name, namelen + 1, (void **) &tmp) == SUCCESS) {
			if ((Z_TYPE_PP(tmp) == IS_ARRAY && Z_ARRVAL_PP(tmp) == &EG(symbol_table)) || *tmp == PS(http_session_vars)) {
				efree(name);
				continue;
			}
		}

		if (has_value) {
			ALLOC_INIT_ZVAL(current);
			if (php_var_unserialize(&current, (const unsigned char **) &p, (const unsigned char *) endptr, &var_hash TSRMLS_CC)) {
				php_set_session_var(name, namelen, current, &var_hash  TSRMLS_CC);
			} else {
				PHP_VAR_UNSERIALIZE_DESTROY(var_hash);
				return FAILURE;
			}
			var_push_dtor_no_addref(&var_hash, &current);
		}
		PS_ADD_VARL(name, namelen);
		efree(name);
	}

	PHP_VAR_UNSERIALIZE_DESTROY(var_hash);

	return SUCCESS;
}

