	if (PQstatus(pgsql) == CONNECTION_OK)
		RETURN_TRUE;

	PQreset(pgsql);
	if (PQstatus(pgsql) == CONNECTION_OK) {
		RETURN_TRUE;
	}
	RETURN_FALSE;
}

