static void  Ins_LOOPCALL( INS_ARG )
{
  PCallRecord  pTCR;

  if ( BOUNDS( args[1], CUR.numFDefs ) || !CUR.FDefs[args[1]].Active )
  {
    CUR.error = TT_Err_Invalid_Reference;
    return;
  }

  if ( CUR.callTop >= CUR.callSize )
  {
    CUR.error = TT_Err_Stack_Overflow;
    return;
  }

  if ( args[0] > 0 )
  {
    pTCR = &CUR.callStack[CUR.callTop];

    pTCR->Caller_Range = CUR.curRange;
    pTCR->Caller_IP    = CUR.IP + 1;
    pTCR->Cur_Count    = (Int)(args[0]);
    pTCR->Cur_Restart  = CUR.FDefs[args[1]].Start;

    CUR.callTop++;

    INS_Goto_CodeRange( CUR.FDefs[args[1]].Range,
                        CUR.FDefs[args[1]].Start );

    CUR.step_ins = FALSE;
  }
}

static UINT32 nsc_rle_encode(BYTE* in, BYTE* out, UINT32 originalSize)
 {
 	UINT32 left;
 	UINT32 runlength = 1;
	UINT32 planeSize = 0;
	left = originalSize;

	while (left > 4 && planeSize < originalSize - 4)
	{
		if (left > 5 && *in == *(in + 1))
		{
			runlength++;
		}
		else if (runlength == 1)
		{
			*out++ = *in;
			planeSize++;
		}
		else if (runlength < 256)
		{
			*out++ = *in;
			*out++ = *in;
			*out++ = runlength - 2;
			runlength = 1;
			planeSize += 3;
		}
		else
		{
			*out++ = *in;
			*out++ = *in;
			*out++ = 0xFF;
			*out++ = (runlength & 0x000000FF);
			*out++ = (runlength & 0x0000FF00) >> 8;
			*out++ = (runlength & 0x00FF0000) >> 16;
			*out++ = (runlength & 0xFF000000) >> 24;
			runlength = 1;
			planeSize += 7;
		}

		in++;
		left--;
	}

	if (planeSize < originalSize - 4)
		CopyMemory(out, in, 4);

	planeSize += 4;
	return planeSize;
}

