tt_cmap4_next( TT_CMap4  cmap )
{
  FT_UInt  charcode;


  if ( cmap->cur_charcode >= 0xFFFFUL )
    goto Fail;

  charcode = cmap->cur_charcode + 1;

  if ( charcode < cmap->cur_start )
    charcode = cmap->cur_start;

  for ( ;; )
  {
    FT_Byte*  values = cmap->cur_values;
    FT_UInt   end    = cmap->cur_end;
    FT_Int    delta  = cmap->cur_delta;


    if ( charcode <= end )
    {
      if ( values )
      {
        FT_Byte*  p = values + 2 * ( charcode - cmap->cur_start );


        do
        {
          FT_UInt  gindex = FT_NEXT_USHORT( p );


          if ( gindex != 0 )
          {
            gindex = (FT_UInt)( ( gindex + delta ) & 0xFFFFU );
            if ( gindex != 0 )
            {
              cmap->cur_charcode = charcode;
              cmap->cur_gindex   = gindex;
              return;
            }
          }
        } while ( ++charcode <= end );
      }
      else
      {
        do
        {
          FT_UInt  gindex = (FT_UInt)( ( charcode + delta ) & 0xFFFFU );


          if ( gindex != 0 )
          {
            cmap->cur_charcode = charcode;
            cmap->cur_gindex   = gindex;
            return;
          }
        } while ( ++charcode <= end );
      }
    }

    if ( tt_cmap4_set_range( cmap, cmap->cur_range + 1 ) < 0 )
      break;

    if ( charcode < cmap->cur_start )
      charcode = cmap->cur_start;
  }

Fail:
  cmap->cur_charcode = 0xFFFFFFFFUL;
  cmap->cur_gindex   = 0;
}

 static int cp2112_gpio_get_all(struct gpio_chip *chip)
 {
 	struct cp2112_device *dev = gpiochip_get_data(chip);
 	struct hid_device *hdev = dev->hdev;
 	u8 *buf = dev->in_out_buffer;
	unsigned long flags;
 	int ret;

	spin_lock_irqsave(&dev->lock, flags);

 	ret = hid_hw_raw_request(hdev, CP2112_GPIO_GET, buf,
 				 CP2112_GPIO_GET_LENGTH, HID_FEATURE_REPORT,
				 HID_REQ_GET_REPORT);
	if (ret != CP2112_GPIO_GET_LENGTH) {
		hid_err(hdev, "error requesting GPIO values: %d\n", ret);
		ret = ret < 0 ? ret : -EIO;
		goto exit;
	}

 	ret = buf[1];

 exit:
	spin_unlock_irqrestore(&dev->lock, flags);

 	return ret;
 }

void BrowserActionsContainer::BrowserActionRemoved(Extension* extension) {
  if (popup_ && popup_->host()->extension() == extension)
    HidePopup();
  int visible_actions = 0;
  for (size_t i = 0; i < browser_action_views_.size(); ++i) {
    if (browser_action_views_[i]->IsVisible())
      ++visible_actions;
  }
  for (std::vector<BrowserActionView*>::iterator iter =
       browser_action_views_.begin(); iter != browser_action_views_.end();
       ++iter) {
    if ((*iter)->button()->extension() == extension) {
      RemoveChildView(*iter);
      delete *iter;
      browser_action_views_.erase(iter);
      animation_target_size_ =
          ClampToNearestIconCount(IconCountToWidth(visible_actions));
      resize_animation_->Reset();
      resize_animation_->SetTweenType(SlideAnimation::EASE_OUT);
      resize_animation_->Show();
      return;
    }
  }
}

DefragDoSturgesNovakTest(int policy, u_char *expected, size_t expected_len)
{
    int i;
    int ret = 0;

    DefragInit();


    int id = 1;
    Packet *packets[17];
    memset(packets, 0x00, sizeof(packets));


    packets[0] = BuildTestPacket(id, 0, 1, 'A', 24);

    packets[1] = BuildTestPacket(id, 32 >> 3, 1, 'B', 16);

    packets[2] = BuildTestPacket(id, 48 >> 3, 1, 'C', 24);

    packets[3] = BuildTestPacket(id, 80 >> 3, 1, 'D', 8);

    packets[4] = BuildTestPacket(id, 104 >> 3, 1, 'E', 16);

    packets[5] = BuildTestPacket(id, 120 >> 3, 1, 'F', 24);

    packets[6] = BuildTestPacket(id, 144 >> 3, 1, 'G', 16);

    packets[7] = BuildTestPacket(id, 160 >> 3, 1, 'H', 16);

    packets[8] = BuildTestPacket(id, 176 >> 3, 1, 'I', 8);


