irc_server_xfer_resume_ready_cb (void *data, const char *signal,
                                 const char *type_data, void *signal_data)
{
    struct t_infolist *infolist;
    struct t_irc_server *ptr_server;
    const char *plugin_name, *plugin_id, *filename;
    int spaces_in_name;

    (void) data;
    (void) signal;
    (void) type_data;

    infolist = (struct t_infolist *)signal_data;

    if (weechat_infolist_next (infolist))
    {
        plugin_name = weechat_infolist_string (infolist, "plugin_name");
        plugin_id = weechat_infolist_string (infolist, "plugin_id");
        if (plugin_name && (strcmp (plugin_name, IRC_PLUGIN_NAME) == 0) && plugin_id)
        {
            ptr_server = irc_server_search (plugin_id);
            if (ptr_server)
            {
                filename = weechat_infolist_string (infolist, "filename");
                spaces_in_name = (strchr (filename, ' ') != NULL);
                irc_server_sendf (ptr_server,
                                  IRC_SERVER_SEND_OUTQ_PRIO_HIGH, NULL,
                                  "PRIVMSG %s :\01DCC RESUME %s%s%s %d %s\01",
                                  weechat_infolist_string (infolist, "remote_nick"),
                                  (spaces_in_name) ? "\"" : "",
                                  filename,
                                  (spaces_in_name) ? "\"" : "",
                                  weechat_infolist_integer (infolist, "port"),
                                  weechat_infolist_string (infolist, "start_resume"));
            }
        }
    }

    weechat_infolist_reset_item_cursor (infolist);

    return WEECHAT_RC_OK;
}

void RenderWidgetHostViewAura::AcceleratedSurfacePostSubBuffer(
    const GpuHostMsg_AcceleratedSurfacePostSubBuffer_Params& params_in_pixel,
    int gpu_host_id) {
 surface_route_id_ = params_in_pixel.route_id;
 if (params_in_pixel.protection_state_id &&
     params_in_pixel.protection_state_id != protection_state_id_) {
   DCHECK(!current_surface_);
   InsertSyncPointAndACK(params_in_pixel.route_id, gpu_host_id, false, NULL);
    return;
 }

 if (ShouldFastACK(params_in_pixel.surface_handle)) {
   InsertSyncPointAndACK(params_in_pixel.route_id, gpu_host_id, false, NULL);
   return;
  }

 current_surface_ = params_in_pixel.surface_handle;
 released_front_lock_ = NULL;
 DCHECK(current_surface_);
 UpdateExternalTexture();

 ui::Compositor* compositor = GetCompositor();
 if (!compositor) {
   InsertSyncPointAndACK(params_in_pixel.route_id, gpu_host_id, true, NULL);
 } else {
   DCHECK(image_transport_clients_.find(params_in_pixel.surface_handle) !=
          image_transport_clients_.end());
   gfx::Size surface_size_in_pixel =
       image_transport_clients_[params_in_pixel.surface_handle]->size();

    gfx::Rect rect_to_paint = ConvertRectToDIP(this, gfx::Rect(
        params_in_pixel.x,
        surface_size_in_pixel.height() - params_in_pixel.y -
           params_in_pixel.height,
        params_in_pixel.width,
        params_in_pixel.height));

   rect_to_paint.Inset(-1, -1);
    rect_to_paint.Intersect(window_->bounds());

    window_->SchedulePaintInRect(rect_to_paint);
   can_lock_compositor_ = NO_PENDING_COMMIT;
   on_compositing_did_commit_callbacks_.push_back(
       base::Bind(&RenderWidgetHostViewAura::InsertSyncPointAndACK,
                  params_in_pixel.route_id,
                  gpu_host_id,
                  true));
   if (!compositor->HasObserver(this))
     compositor->AddObserver(this);
  }
}

PHP_FUNCTION(ini_get_all)
{
	char *extname = NULL;
	int extname_len = 0, extnumber = 0;
	zend_module_entry *module;
	zend_bool details = 1;

	if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "|s!b", &extname, &extname_len, &details) == FAILURE) {
		return;
	}

	zend_ini_sort_entries(TSRMLS_C);

	if (extname) {
		if (zend_hash_find(&module_registry, extname, extname_len+1, (void **) &module) == FAILURE) {
			php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to find extension '%s'", extname);
			RETURN_FALSE;
		}
		extnumber = module->module_number;
	}

	array_init(return_value);
	zend_hash_apply_with_arguments(EG(ini_directives) TSRMLS_CC, (apply_func_args_t) php_ini_get_option, 2, return_value, extnumber, details);
}

