 static int sgi_clock_set(clockid_t clockid, struct timespec *tp)
 {

 	u64 nsec;
	u64 rem;

 	nsec = rtc_time() * sgi_clock_period;

	sgi_clock_offset.tv_sec = tp->tv_sec - div_long_long_rem(nsec, NSEC_PER_SEC, &rem);

 	if (rem <= tp->tv_nsec)
 		sgi_clock_offset.tv_nsec = tp->tv_sec - rem;
	else {
		sgi_clock_offset.tv_nsec = tp->tv_sec + NSEC_PER_SEC - rem;
		sgi_clock_offset.tv_sec--;
	}
	return 0;
}

static void ide_atapi_identify(IDEState *s)
{
    uint16_t *p;

    p = (uint16_t *)s->identify_data;
    if (s->identify_set) {
        goto fill_buffer;
    }
    memset(p, 0, sizeof(s->identify_data));

    put_le16(p + 0, (2 << 14) | (5 << 8) | (1 << 7) | (2 << 5) | (0 << 0));
    padstr((char *)(p + 10), s->drive_serial_str, 20); 
    put_le16(p + 20, 3); 
    put_le16(p + 21, 512); 
    put_le16(p + 22, 4); 
    padstr((char *)(p + 23), s->version, 8); 
    padstr((char *)(p + 27), s->drive_model_str, 40); 
    put_le16(p + 48, 1); 
#ifdef USE_DMA_CDROM
    put_le16(p + 49, 1 << 9 | 1 << 8); 
    put_le16(p + 53, 7); 
    put_le16(p + 62, 7);  
    put_le16(p + 63, 7);  
#else
    put_le16(p + 49, 1 << 9); 
    put_le16(p + 53, 3); 
    put_le16(p + 63, 0x103); 
#endif
    put_le16(p + 64, 3); 
    put_le16(p + 65, 0xb4); 
    put_le16(p + 66, 0xb4); 
    put_le16(p + 67, 0x12c); 
    put_le16(p + 68, 0xb4); 

    put_le16(p + 71, 30); 
    put_le16(p + 72, 30); 

    if (s->ncq_queues) {
        put_le16(p + 75, s->ncq_queues - 1);
        put_le16(p + 76, (1 << 8));
    }

    put_le16(p + 80, 0x1e); 
    if (s->wwn) {
        put_le16(p + 84, (1 << 8)); 
        put_le16(p + 87, (1 << 8)); 
    }

#ifdef USE_DMA_CDROM
    put_le16(p + 88, 0x3f | (1 << 13)); 
#endif

    if (s->wwn) {
        put_le16(p + 108, s->wwn >> 48);
        put_le16(p + 109, s->wwn >> 32);
        put_le16(p + 110, s->wwn >> 16);
        put_le16(p + 111, s->wwn);
    }

    s->identify_set = 1;

fill_buffer:
    memcpy(s->io_buffer, p, sizeof(s->identify_data));
}

bool ber_write_partial_OID_String(TALLOC_CTX *mem_ctx, DATA_BLOB *blob, const char *partial_oid)
{
	TALLOC_CTX *tmp_ctx = talloc_new(mem_ctx);
	char *oid = talloc_strdup(tmp_ctx, partial_oid);
	char *p;

	p = strchr(oid, ':');
	if (p) {
		*p = '\0';
		p++;
	}

	if (!ber_write_OID_String(mem_ctx, blob, oid)) {
		talloc_free(tmp_ctx);
		return false;
	}

	if (p) {
		DATA_BLOB tmp_blob = strhex_to_data_blob(tmp_ctx, p);
		if (!data_blob_append(mem_ctx, blob, tmp_blob.data,
				      tmp_blob.length)) {
			talloc_free(tmp_ctx);
			return false;
		}
	}

	talloc_free(tmp_ctx);

	return true;
}

static struct svc_serv *nfs_callback_create_svc(int minorversion)
{
	struct nfs_callback_data *cb_info = &nfs_callback_info[minorversion];
	struct svc_serv *serv;
	struct svc_serv_ops *sv_ops;

	if (cb_info->serv) {
		svc_get(cb_info->serv);
		return cb_info->serv;
	}

	switch (minorversion) {
	case 0:
		sv_ops = nfs4_cb_sv_ops[0];
		break;
	default:
		sv_ops = nfs4_cb_sv_ops[1];
	}

	if (sv_ops == NULL)
		return ERR_PTR(-ENOTSUPP);

	if (cb_info->users)
 		printk(KERN_WARNING "nfs_callback_create_svc: no kthread, %d users??\n",
 			cb_info->users);

	serv = svc_create(&nfs4_callback_program, NFS4_CALLBACK_BUFSIZE, sv_ops);
 	if (!serv) {
 		printk(KERN_ERR "nfs_callback_create_svc: create service failed\n");
 		return ERR_PTR(-ENOMEM);
	}
	cb_info->serv = serv;
	serv->sv_maxconn = 1024;
	dprintk("nfs_callback_create_svc: service created\n");
	return serv;
}

